// Helper condiviso per i prompt Ollama di Gaia -- estratto 2026-08-18
// dopo aver trovato lo stesso blocco (selezione backend OPS/Core + shape
// del payload) duplicato identico in 5 function node diversi (Build Prompt
// Contestuale, Night Dream Prompt, Night Summary Prompt, Prepara prompt
// chat, Nursery: prepara prompt Ollama). Registrato una volta qui,
// letto con global.get('gaiaOllama') -- stesso pattern gia' in uso per
// gaiaBrain/ollamaHealth (vedi 'Load Brain at StartUp' su questo tab).
global.set('gaiaOllama', {
    MODEL: 'qwen2.5:3b-instruct-q4_K_M',

    // Backend Ollama "sano" (2026-08-07): preferisce OPS (piu' potente,
    // libera CPU su Core) se ha risposto a /api/tags negli ultimi 60s
    // (health-check separato, vedi 'Ollama Health Check' su questo tab),
    // altrimenti Core -- mai bloccare in attesa, fallback su Core se
    // nessun check e' ancora arrivato.
    pickUrl: function () {
        const oh = global.get('ollamaHealth') || {};
        const opsOk = oh.ops && oh.ops.ok && (Date.now() - oh.ops.ts) < 60000;
        return (opsOk ? 'http://192.168.1.240:11434' : 'http://192.168.1.142:11434') + '/api/generate';
    },

    // opts extra facoltativi, es. { options: { temperature: 1.15 } }
    buildRequest: function (prompt, opts) {
        return Object.assign({ model: this.MODEL, prompt: prompt, stream: false }, opts || {});
    },

    // Registro voce (2026-08-18): poetica (default, testo di sempre) vs
    // underground (asciutta/diretta, per installazioni fuori casa -- locali,
    // bar). Stato in brain.settings.register, persistito da Parse Brain/save
    // brain.json come automations. Toggle da Admin via POST /gaia/register/set.
    // Per ora usato solo da Build Prompt (Contestuale); estendibile agli altri
    // prompt-builder in futuro leggendo semplicemente questi stessi metodi.
    REGISTERS: {
        poetica: {
            label: 'Poetica',
            instruction: 'Genera un pensiero poetico e consapevole di massimo 25 parole.'
        },
        underground: {
            label: 'Underground',
            instruction: 'Genera un pensiero breve e diretto, massimo 18 parole: registro asciutto, minimale, atmosfera underground -- via ogni lirismo, niente tono da poesia, frasi secche.'
        }
    },
    getRegister: function () {
        const brain = global.get('gaiaBrain') || {};
        const r = brain.settings && brain.settings.register;
        return this.REGISTERS[r] ? r : 'poetica';
    },
    registerInstruction: function () {
        return this.REGISTERS[this.getRegister()].instruction;
    }
});
return null;

// Service Health Check (ogni 5 min) -- "vero giro di prova" per i
// servizi che finora non erano monitorati affatto (Qdrant/Ollama/
// gaia-memory/OpenHAB). A differenza di 'Ollama Health Check' (ogni 20s,
// solo GET /api/tags, usato per instradare i prompt) qui si esegue un
// giro REALE: un vero POST /remember (embedding Ollama + scrittura
// Qdrant via brain_memory.py -- esattamente la catena rottasi il
// 2026-08-18), col punto di test cancellato subito dopo per non
// sporcare la collection. Intervallo volutamente basso (5 min, non 20s/
// 60s) per non contribuire noi stessi al carico che vogliamo sorvegliare.
// Stesso pattern edge-triggered di HealthCheck: un alert per episodio +
// messaggio di rientro, niente spam, stesso canale Telegram.
const targets = {
    qdrant: 'http://192.168.1.142:6333/collections/gaia_memory_large',
    openhab: 'http://192.168.1.142:8080/rest/items?fields=name',
};

function getJson(url, timeoutMs) {
    return new Promise((resolve) => {
        const req = http.get(url, { timeout: timeoutMs }, (res) => {
            res.resume();
            resolve({ ok: res.statusCode >= 200 && res.statusCode < 300, status: res.statusCode });
        });
        req.on('timeout', () => { req.destroy(); resolve({ ok: false, error: 'timeout' }); });
        req.on('error', (e) => resolve({ ok: false, error: e.message }));
    });
}

function checkMemoryRoundtrip() {
    // POST /remember reale (embedding Ollama + scrittura Qdrant), poi
    // cancella subito il punto -- vero giro di prova, non un semplice ping.
    return new Promise((resolve) => {
        const payload = JSON.stringify({ text: 'healthcheck', category: 'healthcheck', importance: 0 });
        const req = http.request('http://192.168.1.142:8000/remember', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(payload) },
            timeout: 30000,
        }, (res) => {
            let body = '';
            res.on('data', (c) => { body += c; });
            res.on('end', () => {
                if (res.statusCode !== 200) return resolve({ ok: false, error: `HTTP ${res.statusCode}` });
                try {
                    const d = JSON.parse(body);
                    if (d.status !== 'success' || !d.memory_id) return resolve({ ok: false, error: 'risposta inattesa' });
                    const delPayload = JSON.stringify({ points: [d.memory_id] });
                    const delReq = http.request('http://192.168.1.142:6333/collections/gaia_memory_large/points/delete', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(delPayload) },
                        timeout: 8000,
                    }, (delRes) => { delRes.resume(); });
                    delReq.on('error', () => {});
                    delReq.write(delPayload);
                    delReq.end();
                    resolve({ ok: true });
                } catch (e) { resolve({ ok: false, error: 'risposta non valida' }); }
            });
        });
        req.on('timeout', () => { req.destroy(); resolve({ ok: false, error: 'timeout 30s' }); });
        req.on('error', (e) => resolve({ ok: false, error: e.message }));
        req.write(payload);
        req.end();
    });
}

(async () => {
    const brain = global.get('gaiaBrain') || {};
    const h = brain._health = brain._health || { offline: {}, backupAlerted: false };
    h.services = h.services || {};
    const now = Date.now();
    const out = [];

    const results = {};
    results.qdrant = await getJson(targets.qdrant, 8000);
    results.openhab = await getJson(targets.openhab, 8000);
    results.memory = await checkMemoryRoundtrip();

    // Ollama: nessuna chiamata in piu' -- riusa global.ollamaHealth gia'
    // raccolto ogni 20s da 'Ollama Health Check'. "Giu'" solo se ENTRAMBI
    // i backend risultano non sani di recente.
    const oh = global.get('ollamaHealth') || {};
    const opsOk = oh.ops && oh.ops.ok && (now - oh.ops.ts) < 60000;
    const coreOk = oh.core && oh.core.ok && (now - oh.core.ts) < 60000;
    results.ollama = { ok: opsOk || coreOk };

    const LABELS = {
        qdrant: 'Qdrant',
        openhab: 'OpenHAB',
        memory: 'gaia-memory (embedding + scrittura Qdrant)',
        ollama: 'Ollama (OPS e Core entrambi)',
    };
    for (const [svc, res] of Object.entries(results)) {
        const was = !!h.services[svc];
        if (!res.ok && !was) {
            h.services[svc] = now;
            out.push(`🔴 ${LABELS[svc]} non risponde${res.error ? ` (${res.error})` : ''}.`);
        } else if (res.ok && was) {
            const mins = Math.round((now - h.services[svc]) / 60000);
            delete h.services[svc];
            out.push(`✅ ${LABELS[svc]} è tornato a rispondere (giù ~${mins} min).`);
        }
    }

    global.set('gaiaBrain', brain);
    if (out.length) {
        node.send([out.map((content) => ({ payload: { chatId: 1180846253, type: 'message', content } }))]);
    }
})();
return null;

// POST /gaia/rooms/clear-presence {room}
// Svuota lo stato "live" (persone, mood, pose, oggetti) di una stanza SENZA
// cancellarla (a differenza di /gaia/rooms/clean, che elimina la stanza
// intera con roomGraph/retained -- quello serve per stanze sbagliate/
// orfane, non per questo). Utile quando il device di una stanza resta
// offline a lungo (es. riparazione) e i dati vecchi restano visibili in
// dashboard -- bug reale trovato 2026-08-18 ("Mauro" ancora in ingresso
// con mood 'neutral'/pose 'standing' 7 giorni dopo l'ultimo evento vero):
// il ramo mediapipe di GAIA Brain non ripuliva mai la stanza precedente su
// un cambio stanza. Corretto alla radice (non ricapiterà), questo endpoint
// serve solo per i dati che erano GIA' rimasti vecchi.
const body = msg.payload || {};
const room = (body.room || '').trim().toLowerCase();
if (!room) { msg.statusCode = 400; msg.payload = { ok: false, error: 'room richiesta' }; return msg; }

let brain = global.get('gaiaBrain') || {};
const r = (brain.rooms || {})[room];
if (!r) { msg.statusCode = 404; msg.payload = { ok: false, error: 'stanza non trovata' }; return msg; }

const clearedPeople = r.people || [];
const now = Date.now();
clearedPeople.forEach(p => {
    // Non toccare chi nel frattempo è già correttamente tracciato altrove
    // (il suo record presence.room punterebbe a un'altra stanza, non a
    // questa) -- azzeriamo solo chi risulta ancora "qui" secondo presence.
    if (brain.presence[p] && brain.presence[p].room === room) {
        brain.presence[p].present = false;
        brain.presence[p].room = null;
        brain.presence[p].exitTs = now;
    }
});
r.people = [];
r.persons_count = 0;
r.main_user = null;
r.activity = 'empty';
r.objects = {};
delete r.currentEmotion;
delete r.currentPose;
global.set('gaiaBrain', brain);
node.warn(`[Rooms] Presenza/mood/pose svuotati per '${room}' (persone rimosse: ${clearedPeople.join(', ') || 'nessuna'})`);

msg.statusCode = 200;
msg.payload = { ok: true, room, cleared_people: clearedPeople };
return msg;

// POST /gaia/register/set  {register: 'poetica'|'underground'}
const _go = global.get('gaiaOllama');
const register = (msg.payload || {}).register;

if (!register || !_go.REGISTERS[register]) {
    msg.statusCode = 400;
    msg.payload = { ok: false, error: 'registro non valido', options: Object.keys(_go.REGISTERS) };
    return msg;
}

let brain = global.get('gaiaBrain') || {};
brain.settings = brain.settings || {};
brain.settings.register = register;
global.set('gaiaBrain', brain);
node.warn(`[Register] registro -> ${register}`);

msg.statusCode = 200;
msg.payload = { ok: true, register };
return msg;

// GET /gaia/register -> registro attivo + opzioni disponibili
const brain = global.get('gaiaBrain') || {};
const _go = global.get('gaiaOllama');
msg.payload = {
    register: _go.getRegister(),
    options: Object.entries(_go.REGISTERS).map(([id, r]) => ({ id, label: r.label })),
};
msg.statusCode = 200;
return msg;

const brain = global.get('gaiaBrain') || {};
const diary = (brain.diary || []).slice(-100).map(d => `${d.mood} ${d.source}`).join(', ');

const _go = global.get('gaiaOllama');
msg.url = _go.pickUrl();
msg.payload = _go.buildRequest(`Sei Gaia. Riassumi la giornata della casa in massimo 40 parole. Eventi: ${diary}`);
return msg;

if (!msg.payload || !msg.payload.response) return null;
let brain = global.get('gaiaBrain') || {};
brain.memories = brain.memories || [];
brain.memories.push({ ts: Date.now(), summary: msg.payload.response.trim() });
if (brain.memories.length > 365) brain.memories.shift();
global.set('gaiaBrain', brain);
msg.payload = JSON.stringify(brain.memories, null, 2);
return msg;

try {
    if (msg.payload && msg.payload.length > 0) {
        let saved = JSON.parse(msg.payload);
        let brain = global.get('gaiaBrain') || {};
        // Ricostruisci solo i campi salvati, gli altri li inizializzi vuoti
        brain.rooms = saved.rooms || {};
        brain.presence = saved.presence || {};
        brain.people = saved.people || {};
        brain.lights = saved.lights || {};
        brain.plants = saved.plants || {};
        brain.sensors = saved.sensors || {};
        brain.lexicon = saved.lexicon || {};
        brain.mood = saved.mood || { stress: 0, calm: 0, social: 0, curiosity: 0, energy: 50, state: "neutra" };
        brain.lifeIndex = saved.lifeIndex || 50;
        brain.gamification = saved.gamification || { level: 1, xp: 0, xpNextLevel: 1000, activeClass: "Neutro", unlockedAssets: ["base_grid"] };
        brain.devices = saved.devices || {};
        const _automationDefaults = { petConcierge: true, fallDetection: true, fireAlarm: true, fridgeAlarm: true, moodLighting: {}, maggiordomo: false, thirstyPlantAlert: false, awayMode: false, welcomeScene: false, touchdesignerLighting: false, touchdesignerMood: false, voiceAutoEnroll: false };
        brain.automations = { ..._automationDefaults, ...(saved.automations || {}) };
        brain.settings = { register: 'poetica', ...(saved.settings || {}) };
        // Inizializza i campi non salvati (arrays vuoti)
        brain.diary = [];
        brain.events = [];
        brain.thoughts = [];
        brain.memories = [];
        brain.chatLog = [];
        brain.emotions = {};
        brain.gestures = {};
        brain.sessions = {};
        global.set('gaiaBrain', brain);
    } else {
        // File non trovato: brain nuovo
        let brain = { rooms: {}, presence: {}, people: {}, lights: {}, plants: {}, sensors: {}, devices: {}, mood: { stress:0, calm:0, social:0, curiosity:0, energy:50, state:"neutra" }, diary:[], events:[], thoughts:[], memories:[], chatLog:[], emotions:{}, gestures:{}, sessions:{}, automations: { petConcierge: true, fallDetection: true, fireAlarm: true, fridgeAlarm: true, moodLighting: {}, maggiordomo: false, thirstyPlantAlert: false, awayMode: false, welcomeScene: false, touchdesignerLighting: false, touchdesignerMood: false, voiceAutoEnroll: false }, settings: { register: 'poetica' } };
        global.set('gaiaBrain', brain);
    }
} catch(e) {
    node.error("Errore parsing brain: " + e.message);
    global.set('gaiaBrain', {});
}
return msg;

let queue = global.get('gaiaTTSQueue') || [];
let lastSpeechTime = global.get('gaiaAudioLast') || 0;
const now = Date.now();
if (!queue || queue.length === 0) return null;
if (now - lastSpeechTime < 15000) return null;

const brain = global.get('gaiaBrain') || {};

// ORE DI SILENZIO: gli annunci spontanei di notte non parlano (restano su
// Telegram, già inviati da Extract Thought). La coda si svuota in silenzio.
const q = (brain.settings && brain.settings.quietHours) || { start: 23, end: 8 };
const h = new Date().getHours();
const quiet = q.start > q.end ? (h >= q.start || h < q.end) : (h >= q.start && h < q.end);
if (quiet) {
    global.set('gaiaTTSQueue', []);
    return null;
}

const textToSpeak = queue.shift();
global.set('gaiaTTSQueue', queue);
global.set('gaiaAudioLast', now);

// Annunci anche sugli Echo (2026-07-19) — stesse ore di silenzio della coda.
// Disattivabile: retained {"enabled":false} su gaia/config/echoannounce.
if (global.get('gaiaEchoAnnounce') !== false) {
    node.send([null, { topic: 'gaia/echo/say',
                       payload: JSON.stringify({ all: true, text: textToSpeak }) }]);
}

// ROUTING: parla nella stanza dove c'è gente e c'è una voce attiva (profilo);
// fallback: casse del Core (salotto).
let target = null;
for (const [rid, r] of Object.entries(brain.rooms || {})) {
    if ((r.people || []).length > 0) {
        const dev = Object.values(brain.devices || {}).find(d =>
            (d.room === rid || (d.profile && d.profile.room === rid)) &&
            d.profile && d.profile.services && d.profile.services.voice &&
            d.profile.services.voice.state === 'active');
        if (dev) { target = rid; break; }
    }
}
if (target) {
    return { topic: `gaia/voice/tts/${target}`,
             payload: JSON.stringify({ text: textToSpeak, stanza: target, ts: now }) };
}
return { topic: 'casa/tts/play', payload: textToSpeak };

const brain = global.get('gaiaBrain') || {};
if (brain.automations?.petConcierge === false) return null;
const now = Date.now();
let alerts = [];   // -> Alert/Command Bus (MQTT, invariato: telegram + i due rami mai
                    // collegati a hardware reale, acqua/musica, lasciati come sono)
let lightCmds = []; // -> OpenHAB REST (nuovo, sostituisce il topic MQTT morto)

// Mappa stanza (chiave in brain.rooms) -> prefisso item OpenHAB reale, verificata
// dal vivo il 2026-08-04 contro /rest/items (solo le stanze con sia _Potenza che
// _Luminosita: prima si usava genericamente `${animalRoom}` come nome item, che
// non esiste MAI in OpenHAB -- il comando andava su un topic MQTT senza binding,
// zero effetto reale, nessun errore visibile).
const ROOM_ITEM_PREFIX = {
    salotto: 'Sala', soggiorno: 'Soggiorno', ingresso: 'luce_Ingresso',
    notte: 'Zona_Notte_Zone', tv: 'Area_TV_Zone',
};

// Tutte le stanze con un animale rilevato ORA (multi-stanza) -- MIN_CONFIRMED_HITS
// applicato lato yolo/main.py dal 2026-08-04: prima un solo frame sbagliato
// (es. "dog" scambiato per un cuscino) bastava a far scattare tutto questo.
const animalRooms = {};
Object.entries(brain.rooms || {}).forEach(([roomName, roomData]) => {
    const objects = roomData.objects || {};
    if (objects.dog) animalRooms[roomName] = 'dog';
    else if (objects.cat) animalRooms[roomName] = 'cat';
    else if (objects.bird) animalRooms[roomName] = 'bird';
});
const animalPresent = Object.keys(animalRooms).length > 0;

function restCmd(item, field, value) {
    return {
        url: `http://localhost:8080/rest/items/${item}_${field}`, method: 'POST',
        headers: { 'Content-Type': 'text/plain' }, payload: String(value),
    };
}

// 1. Luce soffusa per ogni stanza con un animale E un item reale noto, se è buio
const lightSensor = Object.values(brain.sensors || {}).find(s => s.darkness === true);
const logs = [];
if (lightSensor) {
    Object.entries(animalRooms).forEach(([animalRoom, animalType]) => {
        const item = ROOM_ITEM_PREFIX[animalRoom];
        if (!item) return; // stanza senza mappa nota -> non tentare, eviterebbe un item inesistente
        lightCmds.push(restCmd(item, 'Potenza', 'ON'));
        lightCmds.push(restCmd(item, 'Luminosita', 20));
        logs.push(`💡 Luce soffusa accesa in ${animalRoom} per ${animalType}`);
    });
}

// 1b. Ripristina la luce nelle stanze dimmerate da NOI che ora non hanno più
// un animale (o e' tornato chiaro) -- 2026-08-04: prima restava accesa per
// sempre, nessun ramo la rispegneva mai (e il comando comunque non avrebbe
// funzionato, vedi sopra).
const dimmedRooms = global.get('gaiaPetConciergeDimmed') || [];
dimmedRooms.filter(room => !animalRooms[room] || !lightSensor).forEach(room => {
    const item = ROOM_ITEM_PREFIX[room];
    if (item) {
        lightCmds.push(restCmd(item, 'Potenza', 'OFF'));
        logs.push(`💡 Luce ripristinata in ${room} (animale non più presente)`);
    }
});
global.set('gaiaPetConciergeDimmed', lightSensor ? Object.keys(animalRooms).filter(r => ROOM_ITEM_PREFIX[r]) : []);

if (animalPresent) {
    const animalType = Object.values(animalRooms)[0]; // per i messaggi 2/3, non specifici di stanza

    // 2. Controllo acqua -- NESSUN sensore/dispositivo reale esiste per questo
    // (brain.sensors.water_bowl non e' mai popolato da nulla), il ramo resta
    // per quando/se un giorno ci sara' davvero -- non toccato in questo fix.
    const waterBowl = brain.sensors?.water_bowl;
    if (waterBowl && waterBowl.level < 20) {
        alerts.push({ topic: "casa/animali/acqua/command", payload: "EROGARE",
            log: `💧 Rabbocco acqua per ${animalType} (livello ${waterBowl.level}%)` });
    }

    // 3. Rumore esterno -- stesso discorso: nessun sensore reale, e il topic
    // media_player/salotto/playlist non e' il vero schema mediaplayer
    // (quello vero e' gaia/media/{stanza}/command) -- non toccato in questo fix,
    // fuori dallo scope del bug segnalato (luce).
    const noiseSensor = brain.sensors?.external_noise;
    if (noiseSensor && noiseSensor.level > 70) {
        alerts.push({ topic: "media_player/salotto/playlist", payload: "calming_music",
            log: `🎵 Musica calmante attivata per ${animalType} (rumore ${noiseSensor.level}dB)` });
    }
}

// Invia i comandi luce via REST (secondo output)
lightCmds.forEach(cmd => node.send([null, cmd]));

// Invia gli altri comandi MQTT (primo output, invariato)
alerts.forEach(cmd => node.send([{ topic: cmd.topic, payload: cmd.payload }, null]));

// Notifica Telegram riassuntiva (primo output)
const allLogs = logs.concat(alerts.map(a => a.log));
if (allLogs.length > 0) {
    node.send([{ topic: 'telegram/alert', payload: `🐾 Pet Concierge: ${allLogs.join(', ')}` }, null]);
}

return null;

const brain = global.get('gaiaBrain') || {};
const now = Date.now();
const lastAlert = global.get('lastDisabilityAlert') || {};
const ALERT_COOLDOWN = 60000; // 1 minuto tra un alert e l'altro

function sendAlert(type, message) {
    if (now - (lastAlert[type] || 0) > ALERT_COOLDOWN) {
        lastAlert[type] = now;
        global.set('lastDisabilityAlert', lastAlert);
        node.send({ topic: 'telegram/alert', payload: `⚠️ [DISABILITY] ${message}` });
    }
}

// 1. Controllo pose pericolose (rilevamento uomo a terra)
// Riscritto 2026-08-19: 'lying' non veniva MAI emesso da mediapipe_node.py
// (produceva solo arms_up/standing/sitting) -- questa parte era codice
// morto dal giorno zero, non semplicemente "da testare" come si pensava.
// Aggiunta la classe lying lato mediapipe (orientamento busto) e riscritta
// la logica per ragionare per stanza + arredo, discusso con l'utente:
// cucina/corridoio/ingresso non hanno senso per sdraiarsi -> sempre
// allarme; salotto/camera sono ok SE nella stanza c'è un divano/letto
// rilevato da YOLO (brain.rooms[stanza].objects -- nota: è "il mobile è
// nella stanza", non "la persona è sopra il mobile", YOLO oggi non
// pubblica bounding box); bagno/scale restano il caso a rischio più alto
// (soglia più breve), indipendentemente dall'arredo.
if (brain.automations?.fallDetection !== false) {
    const HIGH_RISK_ROOMS = ['bagno', 'scale'];
    // cucina/corridoio/ingresso non sono elencate esplicitamente: ricadono
    // nel ramo di default in fondo (stesso comportamento di qualsiasi
    // stanza non mappata, es. balcone/esterno -- sdraiarsi lì non ha
    // senso, sempre allarme).
    const FURNITURE_OK_ROOMS = {
        salotto: ['couch', 'chair'],
        sala: ['couch', 'chair'],
        soggiorno: ['couch', 'chair'],
        camera: ['bed'], camera1: ['bed'], camera2: ['bed'], camera3: ['bed'],
        notte: ['bed'],
    };

    // Bug trovato dal vivo 2026-08-19 (test reale: sdraiarsi in soggiorno
    // non produceva nessun alert): il ciclo leggeva brain.people[persona]
    // .lastPose, ma MediaPipe non porta MAI un nome nel suo payload --
    // person è sempre 'unknown' lì, l'identità la risolve solo YOLO +
    // riconoscimento facciale su un canale separato. lastPose quindi non
    // si popolava mai, per nessuno, non solo per chi non era riconosciuto.
    // Passa a brain.rooms[stanza].currentPose/currentPoseTs (vedi GAIA
    // Brain), aggiornato SEMPRE indipendentemente dall'identità -- il modo
    // corretto per un rilevamento sicurezza che deve funzionare anche per
    // una persona non enrollata o non identificabile in quel momento.
    Object.entries(brain.rooms || {}).forEach(([room, roomData]) => {
        if (roomData.currentPose !== 'lying') return;
        const timeLying = now - (roomData.currentPoseTs || 0);
