brain.rooms = brain.rooms || {};
const now = Date.now();

if (!brain.rooms[camera]) {
    brain.rooms[camera] = {
        id: camera, name: camera, persons_count: 0,
        objects: {}, lastUpdate: now, people: [], main_user: null
    };
}
const room = brain.rooms[camera];
room.lastUpdate = now;
room._mediapipe = true;

if (p.person_detected === true) {
    // people_count arriva dal payload multi-persona (minipc); i Pi legacy non
    // lo mandano -> fallback 1. Mai abbassare il conteggio di YOLO, solo alzare.
    const mpCount = p.people_count || 1;
    if ((room.persons_count || 0) < mpCount) {
        room.persons_count = mpCount;
    }
    room.activity = 'present';

    // emotion può essere null se il volto non è visibile (solo body/hands)
    if (p.emotion !== null && p.emotion !== undefined) {
        room.currentEmotion = p.emotion;
    }
    if (p.pose) {
        room.currentPose = p.pose;
    }

    room.mediapipe = {
        emotion:     p.emotion     || null,
        pose:        p.pose        || 'unknown',
        attention:   p.attention   || 'unknown',
        smile_score: p.smile_score || 0,
        mouth_open:  p.mouth_open  || false,
        eyes_open:   p.eyes_open  !== false,
        gesture:     (p.gesture && p.gesture !== 'none') ? p.gesture : null,
        people_count: p.people_count || 1,
        people:      p.people || [],
        ts: now
    };

    const namedPeople = (room.people || []).filter(n => !n.startsWith('unknown'));
    if (namedPeople.length === 1 && p.emotion !== null && p.emotion !== undefined) {
        const sp = namedPeople[0];
        brain.emotions = brain.emotions || {};
        if (!brain.emotions[sp]) brain.emotions[sp] = {};
        brain.emotions[sp].emotion   = p.emotion;
        brain.emotions[sp].attention = p.attention;
        brain.emotions[sp].smile     = p.smile_score;
        brain.emotions[sp].lastSeen  = now;
        brain.presence = brain.presence || {};
        if (!brain.presence[sp]) brain.presence[sp] = {};
        brain.presence[sp].pose     = p.pose;
        brain.presence[sp].lastSeen = now;
    }
} else {
    // Nessuna persona rilevata → azzera
    room.mediapipe = null;
    const hasYoloPeople = (room.people || []).length > 0;
    if (!hasYoloPeople) {
        room.persons_count = 0;
        room.activity = 'idle';
    }
}

global.set('gaiaBrain', brain);
return msg;

let brain = global.get('gaiaBrain') || {};

// Evento diretto dal Presence Engine
if (msg.payload && msg.payload.person && msg.payload.event) {
    msg.event = {
        ts: msg.payload.ts || Date.now(),
        source: 'vision',
        category: 'presence',
        value: msg.payload.event,
