if (typeof brain.lights !== 'object' || brain.lights === null) brain.lights = {};
if (typeof brain.sensors !== 'object' || brain.sensors === null) brain.sensors = {};
if (typeof brain.metrics !== 'object' || brain.metrics === null) brain.metrics = {};
