if (!Array.isArray(brain.thoughts)) brain.thoughts = [];
if (!Array.isArray(brain.memories)) brain.memories = [];
if (!Array.isArray(brain.events)) brain.events = [];
if (typeof brain.presence !== 'object' || brain.presence === null) brain.presence = {};
if (typeof brain.sessions !== 'object' || brain.sessions === null) brain.sessions = {};
if (typeof brain.emotions !== 'object' || brain.emotions === null) brain.emotions = {};
if (typeof brain.gestures !== 'object' || brain.gestures === null) brain.gestures = {};
if (typeof brain.gamification !== 'object' || brain.gamification === null) {
