}
// Grafo stanze (F3): PIANTINA REALE dettata dall'utente 2026-07-09.
// salotto = open space salotto+soggiorno. _v versiona il grafo: alzarla
// sostituisce quello già presente nel brain vivo.
if (!brain.roomGraph || brain.roomGraph._v !== 3) {
    brain.roomGraph = {
        _v: 3,
        ingresso:   ['salotto', 'soggiorno'],
        salotto:    ['ingresso', 'soggiorno', 'cucina', 'corridoio'],
        soggiorno:  ['ingresso', 'salotto'],   // open space col salotto — zona OPS
        cucina:     ['salotto', 'balcone'],
        balcone:    ['cucina'],
        corridoio:  ['salotto', 'sgabuzzino', 'studio', 'camera1', 'camera2', 'bagno', 'camera3', 'bagno2'],
        sgabuzzino: ['corridoio'],
        studio:     ['corridoio'],
        camera1:    ['corridoio'],
        camera2:    ['corridoio'],
        camera3:    ['corridoio'],
        bagno:      ['corridoio'],
        bagno2:     ['corridoio'],
    };
}
if (!brain.roomGraphLearned) brain.roomGraphLearned = {};
if (!brain.roomGraphMotion) brain.roomGraphMotion = {};
// Ore di silenzio per gli ANNUNCI vocali spontanei (pensieri, level-up):
// in quiet hours vanno solo su Telegram. Le risposte ai comandi parlano sempre.
if (!brain.settings) brain.settings = {};
if (!brain.settings.quietHours) brain.settings.quietHours = { start: 23, end: 8 };

let e = msg.event;
const now = Date.now();

const gam = brain.gamification;
gam.stats = gam.stats || { mago: 0, bardo: 0, guerriero: 0, druido: 0 };
gam._cd = gam._cd || {};

const XP_RULES = {
    voce:        { xp: 25,  cls: 'mago',      cd: 15000 },
    pensiero:    { xp: 20,  cls: 'mago',      cd: 120000 },
    presenza:    { xp: 40,  cls: 'bardo',     cd: 60000 },
    gesto:       { xp: 15,  cls: 'guerriero', cd: 60000 },
    movimento:   { xp: 5,   cls: 'guerriero', cd: 300000 },
    natura:      { xp: 10,  cls: 'druido',    cd: 300000 },
    riflessione: { xp: 150, cls: 'druido',    cd: 3600000 },
    rituale:     { xp: 12,  cls: 'mago',      cd: 30000 },
};
// primi 3 esistono in app.js (rpgAssets); i successivi sono nomi riservati
// per asset futuri — syncUnlockedAssets ignora le chiavi che non conosce.
const ASSET_ORDER = ['base_grid', 'ambient_particles_low', 'shield_dome',
    'rune_circle', 'glyph_trail', 'crystal_garden', 'starfield', 'phoenix_core'];
const CLASS_NAME = { mago: 'Mago', bardo: 'Bardo', guerriero: 'Guerriero', druido: 'Druido' };

function _award(kind) {
    const rule = XP_RULES[kind];
    if (!rule) return;
    if (now - (gam._cd[kind] || 0) < rule.cd) return;
    gam._cd[kind] = now;
    gam.xp += rule.xp;
    gam.stats[rule.cls] = (gam.stats[rule.cls] || 0) + 1;

    while (gam.xp >= gam.xpNextLevel) {
        gam.xp -= gam.xpNextLevel;
        gam.level += 1;
        gam.xpNextLevel = Math.round(1000 * Math.pow(gam.level, 1.35) / 50) * 50;

        const nextAsset = ASSET_ORDER.find(a => !(gam.unlockedAssets || []).includes(a));
        if (nextAsset) { gam.unlockedAssets = gam.unlockedAssets || []; gam.unlockedAssets.push(nextAsset); }

        // archetipo: dominante se copre almeno il 35% delle azioni (min 10)
        const entries = Object.entries(gam.stats).sort((a, b) => b[1] - a[1]);
        const tot = entries.reduce((s, x) => s + x[1], 0);
        gam.activeClass = (tot >= 10 && entries[0][1] / tot >= 0.35)
            ? CLASS_NAME[entries[0][0]] : 'Neutro';

        const lvlText = 'Sento nuova forza. Livello ' + gam.level +
            (gam.activeClass !== 'Neutro' ? ', la mia via è ' + gam.activeClass + '.' : '.') +
            (nextAsset ? ' Si è rivelato: ' + nextAsset.replace(/_/g, ' ') + '.' : '');
        brain.thoughts.push({ ts: now, text: lvlText });
        if (brain.thoughts.length > 300) brain.thoughts.shift();
        let _q = global.get('gaiaTTSQueue') || [];
        _q.push(lvlText);
        if (_q.length > 20) _q.shift();
        global.set('gaiaTTSQueue', _q);
        brain.events.push({ ts: now, source: 'rpg', category: 'levelup', value: gam.level, person: null, device: null });
        // terzo output: evento level-up verso MQTT (luci FX, rune, superfici)
        node.send([null, null, { topic: 'gaia/rpg/levelup', payload: JSON.stringify({
            level: gam.level, class: gam.activeClass, asset: nextAsset || null, ts: now }) }]);
    }
}
// Tick sintetico (inject 3s): fa girare decay mood / RPG polling / uscita WS
// anche a casa vuota, senza contare come evento reale.
if (!e && msg.topic === 'gaia/tick') e = { ts: now, source: 'tick', category: 'tick', value: null, person: null, device: null };
if (!e) return null;
if (e.category === 'status' && e.value === 'online' && !e.person) return null;

if (e.category !== 'tick') {
    brain.events.push({ ts: now, source: e.source, category: e.category, value: e.value, person: e.person || null, device: e.device || null });
    if (brain.events.length > 5000) brain.events.shift();
}

// =========================
// LOGICHE SENSORI
// =========================
if (e.source === "plant") {
    const plantId = e.device || "unknown";
    if (!brain.plants[plantId]) brain.plants[plantId] = {};
    brain.plants[plantId].moisture = Number(e.value || 0);
    brain.plants[plantId].lastSeen = now;
    if (e.room) brain.plants[plantId].room = e.room;
}
else if (e.source === "hue") {
    const deviceId = e.device || "unknown";
    if (!brain.lights[deviceId]) brain.lights[deviceId] = { brightness: 0, color: null, power: false, motion: false, colorTemp: null, colorTempAbs: null, alert: 'NONE', lastUpdate: now };
    if (!brain.sensors[deviceId]) brain.sensors[deviceId] = { temperature: null, ambient_light: null, darkness: false, daylight: false, motion: false, battery_low: false, lastUpdate: now };
    const light = brain.lights[deviceId];
    const sensor = brain.sensors[deviceId];
    switch (e.category) {
        case 'ambient_light': sensor.ambient_light = e.value; break;
        case 'temperature': sensor.temperature = e.value; break;
        case 'motion': sensor.motion = e.value; light.motion = e.value; break;
        case 'color': light.color = e.value; break;
        case 'brightness': light.brightness = e.value; break;
        case 'power': light.power = e.value; break;
        case 'color_temperature': light.colorTemp = e.value; break;
        case 'color_temperature_abs': {
            // sentinella spazzatura quando la luce e' spenta o non ha mai riportato un
            // valore reale (osservato via REST 2026-08-05: item Number:Temperature
            // riporta INT32_MAX Kelvin convertito in gradi -> ~2147483373.85; i valori
            // reali Hue stanno nell'intervallo 2000-6500K = 1726.85-6226.85 gradi)
            if (e.value != null && e.value < 10000) light.colorTempAbs = e.value;
            break;
        }
        case 'battery_low': sensor.battery_low = e.value; break;
        case 'battery_level': sensor.battery_level = e.value; break;
        case 'darkness': sensor.darkness = e.value; break;
        case 'daylight': sensor.daylight = e.value; break;
    }
    light.lastUpdate = now; sensor.lastUpdate = now;

    // Sensori fisici → stanza (accoppiamento via MAC nel bridge Hue, 2026-07-17):
    // Sensore ingresso = temp/luce 4 · Sensore corridoio = 5 · corridoio2 = 3
    const HUE_SENSOR_ROOMS = {
        hue_temperature_sensor_4: 'ingresso',  hue_ambient_light_sensor_4: 'ingresso',
        hue_temperature_sensor_5: 'corridoio', hue_ambient_light_sensor_5: 'corridoio',
        hue_temperature_sensor_3: 'corridoio', hue_ambient_light_sensor_3: 'corridoio',
        sensore_ingresso: 'ingresso', sensore_corridoio: 'corridoio', sensore_corridoio2: 'corridoio',
    };
    const devLow = deviceId.toLowerCase();
    const sKey = Object.keys(HUE_SENSOR_ROOMS).find(p => devLow.startsWith(p));
    if (sKey && ['temperature', 'ambient_light', 'darkness', 'motion'].includes(e.category)) {
        const roomName = HUE_SENSOR_ROOMS[sKey];
        if (!brain.rooms[roomName]) brain.rooms[roomName] = { people: [], objects: {} };
        const r = brain.rooms[roomName];
        if (e.category === 'temperature') {
            // il corridoio ha 2 sensori (3 e 5): media dei valori noti
            r._temps = r._temps || {};
            r._temps[devLow] = e.value;
            const vals = Object.values(r._temps).filter(v => v !== null && !isNaN(v));
            if (vals.length) r.temperature = Math.round(vals.reduce((a, b) => a + b, 0) / vals.length * 10) / 10;
        }
        if (e.category === 'ambient_light') r.ambient_light = e.value;
        if (e.category === 'darkness') r.darkness = e.value;
        if (e.category === 'motion' && e.value === true) r.lastMotion = now;
    }
}
else if (e.source === "brick") {
    // Sensori dei mattoni intelligenti (Casa Zero) -- stesso brain.sensors
