    const deviceId = e.device || "unknown";
    if (!brain.sensors[deviceId]) brain.sensors[deviceId] = { temperature: null, humidity: null, vibration: null, air_quality: null, lastUpdate: now };
    const sensor = brain.sensors[deviceId];
    if (["temperature", "humidity", "vibration", "air_quality"].includes(e.category)) {
        sensor[e.category] = e.value;
    }
    sensor.lastUpdate = now;
    if (e.room && !brain.rooms[e.room]) brain.rooms[e.room] = { people: [], objects: {} };
}
else if (e.source === "alexa" && e.category === "speech") {
