    brain.voiceCommands = brain.voiceCommands || [];
    brain.voiceCommands.push({ text: e.value, ts: now, stanza: e.room, via: 'alexa' });
    if (brain.voiceCommands.length > 20) brain.voiceCommands.shift();
}
