    // sempre person='unknown' (non porta mai un nome, vedi commento lì).
    // Se una stanza avesse copertura mediapipe ma non ancora un evento YOLO/
    // identity, l'oggetto stanza non esisterebbe affatto e le scritture di
    // mood/pose più sotto (currentPose/currentEmotion) andrebbero a vuoto
    // in silenzio (guardia "if (brain.rooms[roomId])" che salva da un
    // crash ma nasconde il problema).
    if (roomId && !brain.rooms[roomId]) {
        brain.rooms[roomId] = { id: roomId, name: roomId, persons_count: 0, objects: {}, lastUpdate: now, people: [], main_user: null };
    }

    // Only update presence + room.people for KNOWN people
    // MediaPipe detects presence but can't name people — that's face recognition's job
    if (e.person !== 'unknown' && roomId) {
        // Bug trovato dal vivo 2026-08-18 ("Mauro" ancora in ingresso con
        // mood/pose fantasma nonostante nessun device attivo li' da giorni):
        // questo ramo aggiungeva la persona alla stanza nuova ma non la
        // toglieva mai da quella precedente (a differenza del ramo identity
        // qualche riga sotto, che questo ciclo lo fa gia'). Risultato: una
        // persona tracciata via mediapipe restava "presente" per sempre in
        // OGNI stanza in cui era mai stata vista, e la stanza vecchia non
        // scendeva mai a persons_count 0 -- ne' il timeout 90s ne' il
        // "Cleanup Stanze Stale" (4h, gated su persons_count===0) potevano
        // mai scattare.
        const previousRoom = brain.presence[e.person] ? brain.presence[e.person].room : null;
        if (!brain.presence[e.person]) {
            brain.presence[e.person] = { present: true, room: roomId, lastSeen: now, confidence: e.confidence || 0.5, enterTs: now };
        } else {
            brain.presence[e.person].present = true;
            brain.presence[e.person].lastSeen = now;
            brain.presence[e.person].confidence = e.confidence || brain.presence[e.person].confidence;
            brain.presence[e.person].room = roomId;
            if (!brain.presence[e.person].enterTs) brain.presence[e.person].enterTs = now;
        }
        if (previousRoom && previousRoom !== roomId && brain.rooms[previousRoom]) {
            const pr = brain.rooms[previousRoom];
            pr.people = (pr.people || []).filter(p => p !== e.person);
            pr.persons_count = pr.people.length;
            if (pr.main_user === e.person) pr.main_user = pr.people[0] || null;
            if (pr.persons_count === 0) {
                pr.activity = 'empty';
                delete pr.currentEmotion;
                delete pr.currentPose;
            }
        }
        if (!brain.rooms[roomId]) {
            brain.rooms[roomId] = { id: roomId, name: roomId, persons_count: 0, objects: {}, lastUpdate: now, people: [], main_user: null };
        }
        if (!brain.rooms[roomId].people.includes(e.person)) {
            brain.rooms[roomId].people.push(e.person);
