    if (e.category === 'emotion') {
        if (e.person !== 'unknown') {
            if (!brain.emotions[e.person]) brain.emotions[e.person] = {};
            brain.emotions[e.person].emotion = e.value;
            brain.emotions[e.person].confidence = e.confidence;
            brain.emotions[e.person].lastSeen = now;
        }
        if (roomId && brain.rooms[roomId]) {
            brain.rooms[roomId].currentEmotion = e.value;
            if (brain.rooms[roomId].people?.length === 1) {
