            // segnale, non quello per-persona -- altrimenti non scatta per
            // NESSUNO, non solo per chi non è riconosciuto.
            if (brain.rooms[roomId].currentPose !== e.value) brain.rooms[roomId].currentPoseTs = now;
            brain.rooms[roomId].currentPose = e.value;
            if (brain.rooms[roomId].people?.length === 1) {
                const sp2 = brain.rooms[roomId].people[0];
                if (!brain.presence[sp2]) brain.presence[sp2] = {};
                brain.presence[sp2].pose = e.value;
            }
        }
    }
}
else if (e.source === "vision") {
    let roomId = e.node || e.camera || e.device || "salotto";
    let zoneName = e.zone || null;
    if (!brain.rooms[roomId]) {
        brain.rooms[roomId] = {
            id: roomId, name: roomId, persons_count: 0, objects: {},
            lastUpdate: now, people: [], main_user: null, zone: zoneName
        };
    } else if (zoneName && !brain.rooms[roomId].zone) {
        brain.rooms[roomId].zone = zoneName;
    }

    // ---------- PRESENZA ----------
    if (e.category === 'presence') {
        let person = e.person ? e.person.toLowerCase().trim() : 'unknown';
        let eventType = e.value;
        if (eventType === 'person_entered') eventType = 'enter';
        if (eventType === 'person_left') eventType = 'exit';
        if (eventType === 'enter') {
            if (person !== 'unknown') {
                let unknownsToRemove = [...brain.rooms[roomId].people].filter(p => p.startsWith('unknown'));
                for (let unknown of unknownsToRemove) {
                    brain.rooms[roomId].people = brain.rooms[roomId].people.filter(p => p !== unknown);
                    if (brain.presence[unknown]) {
                        brain.presence[unknown].present = false;
                        brain.presence[unknown].room = null;
                    }
                }
            }
            if (!brain.presence[person]) brain.presence[person] = { present: false, room: null, lastSeen: 0, confidence: 0, enterTs: now };
            brain.presence[person].present = true;
            brain.presence[person].room = roomId;
            brain.presence[person].lastSeen = now;
            brain.presence[person].confidence = e.confidence || 0.5;
            if (!brain.presence[person].enterTs) brain.presence[person].enterTs = now;
