        const ok = before.length !== (global.get('gaiaReminders') || []).length;
        node.warn(`[Promemoria] annulla #${id} da Telegram → ${ok ? 'ok' : 'non trovato'}`);
        msg.payload = { chatId, type: 'message', content: ok ? `🗑 Promemoria #${id} annullato.` : `Nessun promemoria #${id}.` };
        return [null, msg, null];
    }

    if ((m2 = args.match(/^(\S+)\s+(\d+(?:\.\d+)?)\s+(.+)$/))) {
        const room = m2[1].toLowerCase();
        const delay = parseFloat(m2[2]);
        const text = m2[3].trim();
        const seq = (global.get('gaiaReminderSeq') || 0) + 1;
        global.set('gaiaReminderSeq', seq);
        const due_ts = Date.now() + Math.round(delay * 60000);
        const list = global.get('gaiaReminders') || [];
        list.push({ id: seq, room, text, due_ts });
        global.set('gaiaReminders', list);
        node.warn(`[Promemoria] #${seq} creato da Telegram: ${room} tra ${delay}min — "${text}"`);
        msg.payload = { chatId, type: 'message',
            content: `⏰ Promemoria #${seq} fra ${delay} min in ${room}: "${text}"` };
        return [null, msg, null];
    }

    msg.payload = { chatId, type: 'message',
        content: 'Formato: /promemoria <stanza> <minuti> <testo>\nEs: /promemoria cucina 10 togli la pasta\n/promemoria annulla <id> · /promemoria (lista)' };
    return [null, msg, null];
}

// ── /dillo: far parlare Gaia su Echo/voce (Telegram non serve: l'hai già scritto tu) ──
const dilloMatch = t.match(/^\/?dillo(?:\s+(.+))?$/i);
if (dilloMatch) {
    const KNOWN_ROOMS = ['cucina', 'soggiorno', 'bagno', 'ingresso', 'salotto'];
    const VOICE_ROOMS = ['ingresso', 'soggiorno', 'salotto'];
    const args = (dilloMatch[1] || '').trim();
    if (!args) {
        msg.payload = { chatId, type: 'message',
            content: 'Formato: /dillo [stanza] <testo>\nEs: /dillo cucina Il forno è pronto\nSenza stanza: dappertutto.' };
        return [null, msg, null];
    }
    const words = args.split(/\s+/);
    const maybeRoom = words[0].toLowerCase();
    let room = null, text = args;
    if (KNOWN_ROOMS.includes(maybeRoom) && words.length > 1) {
        room = maybeRoom;
        text = words.slice(1).join(' ');
    }
    const ECHO_ROOMS = ['cucina', 'soggiorno', 'bagno'];   // uniche stanze con un Echo fisico (vedi EchoSay)
    const outs = [];
    if (room) {
        outs.push({ topic: 'gaia/echo/say', payload: JSON.stringify({ room, text }) });
        outs.push({ topic: `gaia/voice/tts/${room}`, payload: JSON.stringify({ text }) });
        const via = [];
        if (ECHO_ROOMS.includes(room)) via.push('Echo');
        if (VOICE_ROOMS.includes(room)) via.push('voce Gaia');
        const viaTxt = via.length ? ` (${via.join(' + ')})` : ' — ⚠️ nessun altoparlante noto lì, nulla da sentire';
        msg.payload = { chatId, type: 'message', content: `🔊 Detto in ${room}${viaTxt}: "${text}"` };
    } else {
        outs.push({ topic: 'gaia/echo/say', payload: JSON.stringify({ all: true, text }) });
        VOICE_ROOMS.forEach(r => outs.push({ topic: `gaia/voice/tts/${r}`, payload: JSON.stringify({ text }) }));
        msg.payload = { chatId, type: 'message', content: `🔊 Detto ovunque: "${text}"` };
    }
    return [null, msg, outs];
}

