// ── Comandi servizi (multi-device, guidati dai profili semantici) ──────────
const svcMatch = t.match(/^\/?(attiva|disattiva|start|stop|abilita|disabilita)\s+(yolo|mediapipe|voice|screen|scene|kiosk|mediaplayer|herbarium|herbsim|herbmp)(?:\s+(\S+))?/i);
if (svcMatch || t === '/servizi' || t === '/pi' || t === '/device') {
    const now_ = Date.now();
    const devices = Object.values(brain.devices || {}).filter(d =>
        d.profile && d.online !== false && (now_ - (d.lastSeen || 0)) < 180000);

    if (!svcMatch) {
        // Testo PLAIN, niente parse_mode Markdown: device_id/nomi servizio
        // dinamici (es. dmx_kick_enable, mocap_bridge) possono contenere un
        // numero DISPARI di '_' nell'insieme del messaggio -- Telegram
        // richiede i delimitatori Markdown bilanciati su tutto il testo,
        // altrimenti l'API rifiuta l'invio in silenzio (trovato dal vivo
        // 2026-08-26: 65 underscore, /servizi e /device non rispondevano
        // piu' da quando i device DMX sono stati aggiunti). Qui il rischio
        // e' strutturale (nomi non sotto il nostro controllo, cambiano ad
        // ogni nuovo device) quindi niente markup invece di inseguire il
        // bilanciamento ogni volta.
        let reply = '📡 Device e servizi GAIA\n';
        devices.forEach(d => {
            reply += `\n▸ ${d.room || d.id} — ${d.id} (${d.role || '?'})\n`;
            Object.entries(d.profile.services || {}).forEach(([k, v]) => {
                if (k === 'camera') return;   // dipendenza automatica, non toggolabile
                reply += `  ${v.state === 'active' ? '🟢' : '⚪️'} ${k}\n`;
            });
        });
        reply += '\n/attiva <servizio> [stanza] · /disattiva <servizio> [stanza]\n';
        reply += 'Servizi: yolo · mediapipe · voice · screen · scene · kiosk · mediaplayer · herbarium · herbsim · herbmp\n(schermo Pi: kiosk/screen si escludono a vicenda, herbsim/herbmp idem)\n';
        reply += 'Senza stanza agisce su TUTTI i device che hanno quel servizio.\n';
        reply += '/stato per il report completo della casa.\nTocca un bottone sotto per accendere/spegnere al volo.';

        // Bottoni tocca-per-attivare: solo i servizi davvero toggolabili via
        // /attiva (stesso elenco della regex svcMatch sopra) -- non i
        // servizi TD/DMX/PatchDeck (register_service di gaia_device_agent,
        // decine/centinaia per device, non pensati per essere accesi da
        // Telegram). callback_data = "svc:<device_id>:<servizio>", il
        // gestore dei tap (vedi nodo "Telegram Callback") rilegge lo stato
        // fresco al momento del tocco invece di fidarsi di quello mostrato
        // qui (puo' essere cambiato nel frattempo).
        const TOGGLEABLE = new Set(['yolo','mediapipe','voice','screen','scene','kiosk','mediaplayer','herbarium','herbsim','herbmp']);
        const inlineRows = [];
        devices.forEach(d => {
            Object.entries(d.profile.services || {}).forEach(([k, v]) => {
                if (!TOGGLEABLE.has(k)) return;
                inlineRows.push([{
                    text: `${v.state === 'active' ? '🟢' : '⚪️'} ${d.room || d.id} · ${k}`,
                    callback_data: `svc:${d.id}:${k}`,
                }]);
            });
        });
        const options = inlineRows.length ? { reply_markup: { inline_keyboard: inlineRows } } : undefined;
        msg.payload = { chatId, type: 'message', content: reply, ...(options ? { options } : {}) };
        return [null, msg, null];
    }

    const action  = /^(attiva|start|abilita)$/i.test(svcMatch[1]) ? 'enable' : 'disable';
    const service = svcMatch[2].toLowerCase();
    const where   = (svcMatch[3] || '').toLowerCase();

    let targets = devices.filter(d => (d.profile.services || {})[service]);
    if (where) {
        targets = targets.filter(d =>
            (d.room || '').toLowerCase() === where || d.id.toLowerCase().includes(where));
    }
    if (!targets.length) {
        msg.payload = { chatId, type: 'message',
            content: `Nessun device con \"${service}\"${where ? ` in ${where}` : ''}.` };
        return [null, msg, null];
    }

    const emoji = action === 'enable' ? '✅' : '🔴';
    const verb  = action === 'enable' ? 'abilitato' : 'disabilitato';
    const mqttMsgs = targets.map(d => ({
        topic:   `gaia/device/${d.id}/command`,
        payload: JSON.stringify({ action, service })
    }));
    const names = targets.map(d => d.room || d.id).join(', ');
    const replyMsg = { ...msg, payload: { chatId, type: 'message',
        content: `${emoji} ${service} ${verb} su: ${names}` } };
    return [null, replyMsg, mqttMsgs];
}
