const _oh = global.get('ollamaHealth') || {};
const _opsOk = _oh.ops && _oh.ops.ok && (Date.now() - _oh.ops.ts) < 60000;
const _ollamaUrl = (_opsOk ? 'http://192.168.1.240:11434' : 'http://192.168.1.142:11434') + '/api/generate';
