return msg;

const brano = msg.entita.brano || '';
msg.tts_text = brano ? 'Metto ' + brano : 'Avvio la musica.';

node.send([
    msg,
    {
        topic: 'gaia/home/music/play',
        payload: JSON.stringify({ brano: brano, stanza: msg.stanza })
    }
]);
return null;

const { valore, unita } = msg.entita;
if (!valore) {
    msg.tts_text = 'Non ho capito la durata del timer.';
    return msg;
}
const unitaLabel = unita && unita.startsWith('second') ? 'secondi' :
                   unita && unita.startsWith('or')     ? (valore === 1 ? 'ora' : 'ore') :
                   (valore === 1 ? 'minuto' : 'minuti');
msg.tts_text = 'Timer impostato per ' + valore + ' ' + unitaLabel + '.';

// Calcola ms
const ms = unita && unita.startsWith('second') ? valore * 1000 :
           unita && unita.startsWith('or')     ? valore * 3600000 :
           valore * 60000;

const stanza = msg.stanza;
setTimeout(() => {
    node.send([null, {
        topic: 'gaia/voice/tts/' + stanza,
        payload: JSON.stringify({ text: 'Timer scaduto!', stanza: stanza, ts: Date.now() })
    }]);
}, ms);

return [msg, null];

const risposte = [
    'Non ho capito. Puoi ripetere?',
    'Scusa, non ho compreso. Riprova.',
    'Non sono sicura di aver capito. Puoi riformulare?'
];
msg.tts_text = risposte[Math.floor(Math.random() * risposte.length)];
return msg;

msg.topic   = 'gaia/voice/tts/' + msg.stanza;
msg.payload = JSON.stringify({
    text:   msg.tts_text,
    stanza: msg.stanza,
    intent: msg.intent,
    ts:     Date.now()
});

// 'minipc' (Core) non ha un vero servizio voice che consuma
// gaia/voice/tts/{stanza} per parlare -- quel topic aggiorna solo il
// tracker per dashboard/TD (tts_any_extract_fn, gaiaLastTtsAny), non
// produce mai audio. L'altoparlante reale di Core ascolta casa/tts/play
// (say.sh -> Piper -> aplay) -- senza questo bridge le risposte dirette
// a 'minipc' (es. stato_sistema, "come stai") restavano mute: testo in
// dashboard, mai sentite. Bug preesistente (non la migrazione OPS di
// ieri), trovato il 2026-08-08.
if (msg.stanza === 'minipc') {
    node.send({ topic: 'casa/tts/play', payload: msg.tts_text });
}

return msg;

const parts = msg.topic.split('/');
const stanza = parts[3];
const stati = flow.get('voice_status') || {};
// Payload vuoto = retained cancellato (voice spento/stanza pulita) → via
// l'entry invece di sporcare i log con errori di parse.
let p = msg.payload;
if (Buffer.isBuffer(p)) p = p.toString('utf8');
if (typeof p === 'string') {
    if (!p.trim()) { delete stati[stanza]; flow.set('voice_status', stati); return null; }
    try { p = JSON.parse(p); } catch (e) { return null; }
}
if (!p || typeof p !== 'object') return null;
stati[stanza] = {
    state:  p.state,
    ts:     p.ts,
    aggiornato: Date.now()
};
flow.set('voice_status', stati);
return null;

const parts = msg.topic.split('/');
const stanza = parts[3] || 'sconosciuta';
const persone = flow.get('persone_in_casa') || { totale: 0, stanze: {} };

const count = msg.payload.count || 0;
persone.stanze[stanza] = { count, ts: Date.now() };

// Rimuovi stanze non aggiornate da più di 30s
const ora = Date.now();
Object.keys(persone.stanze).forEach(s => {
    if (ora - persone.stanze[s].ts > 30000) delete persone.stanze[s];
});

persone.totale = Object.values(persone.stanze).reduce((a, s) => a + s.count, 0);
flow.set('persone_in_casa', persone);
return null;

const raw = (msg.payload && (msg.payload.message || msg.payload.response || '')) || msg.tts_text || '';

// Usa l'intent estratto client-side da Prepara prompt chat (priorità assoluta)
let action = msg.action_override || null;

// Pulizia testo: rimuovi eventuali ACTION: rimasti (per sicurezza)
let text = raw
    .replace(/\n?ACTION:[^\n]*/g, '')
    .replace(/^\s*\{.*?\}\s*$/gm, '')
    .replace(/\n{3,}/g, '\n')
    .trim();

// Testo di fallback se vuoto
if (!text) {
    text = action
        ? (action.tipo === 'stato' ? 'Ecco come mi sento.' : 'Fatto.')
        : 'Certo.';
}

msg.payload  = { person: msg.payload.person || msg.person || 'Gaia', message: text, ts: msg.payload.ts || Date.now() };
msg.tts_text = text;
msg.gaiaAction = action;

// Out 1 → Prepara TTS | Out 2 → ActionRouter | Out 3 → HTTP Response (solo se req attiva)
return [msg, action ? msg : null, msg.res ? msg : null];

const action = msg.gaiaAction;
if (!action || !action.tipo) return null;

// Out 1 → HueExecutor (tipo=hue)
// Out 2 → GaiaExpression (tipo=stato)
// Out 3 → (futuro: musica, three.js diretto, ecc.)
if (action.tipo === 'hue') return [msg, null, null];
if (action.tipo === 'stato') return [null, msg, null];
return null;

