// chi configura TouchDesigner deve puntare direttamente all'item OpenHAB reale.
const parts = msg.topic.split('/');
if (parts.length !== 5 || parts[2] !== 'lighting') return null;
const item = parts[3];
const field = parts[4];
const ALLOWED_FIELDS = ['Potenza', 'Luminosita', 'Colore', 'Color_Temperature'];
if (!ALLOWED_FIELDS.includes(field)) return null;

// throttle: max 1 comando per item+campo ogni 200ms, TouchDesigner puo' mandare
// molto piu' spesso di quanto OpenHAB debba/possa incassare
const now = Date.now();
const lastSent = global.get('tdLightingLastSent') || {};
const key = `${item}_${field}`;
if (now - (lastSent[key] || 0) < 200) return null;
lastSent[key] = now;
global.set('tdLightingLastSent', lastSent);

let payload = msg.payload;
if (typeof payload === 'object') payload = JSON.stringify(payload);
return {
    url: `http://localhost:8080/rest/items/${item}_${field}`, method: 'POST',
    headers: { 'Content-Type': 'text/plain' }, payload: String(payload)
};

// GET /gaia/room-guess?room=<chiave_stanza_attuale>
// Non assegna nulla — suggerisce solo la stanza piu' probabile in base agli
// oggetti YOLO visti da quella telecamera, stesse firme del Device Registry
// (yoloVerify) ma usate per indovinare invece che per verificare una claim.
const brain = global.get('gaiaBrain') || {};
const room = (msg.req.query.room || '').trim();

const ROOM_SIGNATURES = {
    salotto:   ['couch', 'tv', 'chair', 'potted plant', 'remote'],
    sala:      ['dining table', 'chair', 'cup', 'bowl'],
    cucina:    ['refrigerator', 'bowl', 'cup', 'bottle', 'microwave', 'oven'],
    camera:    ['bed', 'person'],
    bagno:     ['toilet', 'sink', 'toothbrush'],
    studio:    ['laptop', 'keyboard', 'monitor', 'chair', 'book'],
    ingresso:  ['person', 'chair', 'backpack', 'handbag', 'umbrella'],
    garage:    ['car', 'bicycle', 'motorcycle'],
    giardino:  ['bicycle', 'dog', 'cat', 'potted plant'],
};

if (!room) {
    msg.statusCode = 400;
    msg.payload = { ok: false, error: 'query param "room" obbligatorio (chiave stanza attuale in brain.rooms)' };
    return msg;
}

const roomData = (brain.rooms || {})[room];
const objects = roomData?.objects || {};
const detectedObjs = Object.keys(objects).map(k => k.toLowerCase());

if (detectedObjs.length === 0) {
    msg.statusCode = 200;
    msg.payload = { ok: true, room, candidates: [], best: null,
                    message: 'Nessun oggetto rilevato ancora da questa telecamera' };
    return msg;
}

const candidates = Object.entries(ROOM_SIGNATURES).map(([candidateRoom, sig]) => {
    const matches = sig.filter(s => detectedObjs.some(d => d.includes(s)));
    const score = Math.round((matches.length / sig.length) * 100);
    return { room: candidateRoom, score, matched_objects: matches };
}).sort((a, b) => b.score - a.score);

msg.statusCode = 200;
msg.payload = {
    ok: true,
    room,
    detected_objects: detectedObjs,
    candidates,
    best: candidates[0]?.score > 0 ? candidates[0] : null,
};
return msg;

// Le risposte ai comandi vocali dati al minipc arrivano qui come JSON
// {text, stanza, intent, ts} (da "Build TTS payload"/"Timer", tab GAIA Voice).
// SOLO tracker dashboard/TD (gaiaLastTts) -- l'audio del Core passa da
// casa/tts/play (say.sh -> Piper -> aplay), inviato a parte da "Build TTS
// payload" quando stanza === 'minipc'. Fino al 2026-08-10 questo nodo era
// wired anche su "Clean Text" -> "Speak", causando OGNI risposta diretta al
// Core detta DUE VOLTE (stesso testo, due percorsi MQTT diversi convergenti
// sullo stesso exec). Wire rimosso: non ricollegare a Clean Text.
let text = '';
try {
    const p = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;
    text = (p && p.text || '').toString().trim();
} catch (e) {
    text = (msg.payload || '').toString().trim();
}
if (!text) return null;
// Vocabolario Asemico: espone l'ultimo TTS al payload WS (ThreeViewEngineGAME
// legge gaiaLastTts) cosi' la welcome puo' "scrivere" cio' che Gaia dice.
global.set('gaiaLastTts', { text: text, ts: Date.now() });
msg.payload = text;
return msg;

// Profilo semantico dei device (docs/gaia-semantico.md, contratto 1).
// Retained per-device: capability hardware + servizi con endpoint.
let p = msg.payload;
if (typeof p === 'string') { try { p = JSON.parse(p); } catch (e) { return null; } }
if (!p || !p.device_id) return null;

let brain = global.get('gaiaBrain') || {};
brain.devices = brain.devices || {};
const d = brain.devices[p.device_id] || { id: p.device_id };
d.profile  = p;
d.role     = p.role || d.role;
d.ip       = p.ip || d.ip;
d.lastSeen = Date.now();
d.online   = true;

// F4: capability → moduli suggeriti (l'hardware decide cosa si PUÒ attivare;
// l'attivazione resta opt-in dell'utente da Pi Manager)
const CAP_MODULES = {
    camera:    ['camera', 'yolo', 'mediapipe'],
    mic:       ['voice'],
    audio_out: ['tts', 'mediaplayer'],
    display:   ['kiosk-welcome'],
    midi:      ['av-herbarium'],
    i2c:       ['av-herbarium'],
};
const caps = p.capabilities || {};
const sugg = new Set();
for (const [cap, mods] of Object.entries(CAP_MODULES)) {
    const v = caps[cap];
    if (v && (!Array.isArray(v) || v.length)) mods.forEach(m => sugg.add(m));
}
d.suggested_modules = [...sugg];
brain.devices[p.device_id] = d;
global.set('gaiaBrain', brain);
return null;

// Tutti i profili device noti — consumato da cameras.html e dal
// scene worker per scoprire gli endpoint (mjpeg, tts, ...) senza hardcode.
const brain = global.get('gaiaBrain') || {};
const out = {};
for (const [id, d] of Object.entries(brain.devices || {})) {
    if (d.profile) out[id] = { ...d.profile, room_assigned: d.room || d.profile.room, suggested_modules: d.suggested_modules || [] };
}
msg.payload = out;
msg.headers = { 'Access-Control-Allow-Origin': '*' };
return msg;

// Chi sta parlando in una stanza (F3 gaia-semantico).
// Due vie: (a) il voice della stanza registra un comando (alta confidenza);
// (b) parlato normale = volume mic alto + BOCCA APERTA da mediapipe (la
// conferma visiva evita che il rumore ambientale accenda il badge).
let p = msg.payload;
if (typeof p === 'string') { try { p = JSON.parse(p); } catch (e) { return null; } }
const stanza = (msg.topic || '').split('/').pop();
if (!stanza || !p) return null;

let brain = global.get('gaiaBrain') || {};
brain.rooms = brain.rooms || {};
const room = brain.rooms[stanza];
if (!room) return null;

const named = (room.people || []).filter(n => !String(n).startsWith('unknown'));
if (!named.length) return null;
const mpPeople = (room.mediapipe && room.mediapipe.people) || [];
const mouthOpen = mpPeople.some(x => x.mouth_open);

let who = null, conf = 0;
const isStats = msg.topic.includes('/stats/');
if (isStats) {
    // (b) parlato normale: volume sopra soglia E bocca aperta
    const vol = p.vol || 0;
    const thr = p.silence_threshold || p.threshold || 400;
    if (vol > thr && mouthOpen) {
        who = named[0];
        conf = named.length === 1 ? 0.7 : 0.4;
    }
} else {
    // (a) comando vocale in corso
    const state = p.state || p.status;
    if (state === 'recording' || state === 'processing') {
        if (named.length === 1) { who = named[0]; conf = 0.9; }
        else if (mouthOpen)     { who = named[0]; conf = 0.5; }
    }
}

if (who) {
    room.speaking = { name: who, ts: Date.now(), confidence: conf };
    global.set('gaiaBrain', brain);
}
return null;

// Descrizioni scena dal worker VLM (F5): com'è fatta ogni stanza.
let p = msg.payload;
if (typeof p === 'string') { try { p = JSON.parse(p); } catch (e) { return null; } }
if (!p || !p.room || !p.description) return null;
let brain = global.get('gaiaBrain') || {};
brain.rooms = brain.rooms || {};
brain.rooms[p.room] = brain.rooms[p.room] || { id: p.room, name: p.room, people: [] };
const prevScene = (brain.rooms[p.room].scene || {}).text;
brain.rooms[p.room].scene = { text: p.description, model: p.model, ts: p.ts || Date.now() };
// una stanza che CAMBIA aspetto incuriosisce (sorgente mood curiosity)
if (prevScene && prevScene !== p.description && brain.mood) {
    brain.mood.curiosity = Math.min(1, (brain.mood.curiosity || 0) + 0.1);
}
global.set('gaiaBrain', brain);
return null;

// GET /gaia/rooms → stato stanze note al brain + device assegnati.
// Serve all'admin per vedere/pulire stanze orfane (device spostati).
const brain = global.get('gaiaBrain') || {};
const devices = Object.values(brain.devices || {});
const graphRooms = Object.keys(brain.roomGraph || {}).filter(k => k !== '_v');
const out = {};
const devIn = name => devices.filter(d => d.room === name).map(d => d.id);
for (const [name, r] of Object.entries(brain.rooms || {})) {
    out[name] = {
        in_map:      graphRooms.includes(name),
        devices:     devIn(name),
        people:      r.people || [],
        speaking:    r.speaking || null,
        has_scene:   !!r.scene,
        last_update: r.lastUpdate || r.ts || null,
    };
}
for (const name of graphRooms) {
    if (!out[name]) out[name] = { in_map: true, devices: devIn(name), people: [],
                                  speaking: null, has_scene: false, last_update: null };
}
msg.payload = { rooms: out, ts: Date.now() };
msg.headers = { 'Access-Control-Allow-Origin': '*' };
return msg;

// POST /gaia/rooms/clean {room, force?}
// Rimuove una stanza sbagliata/orfana: dati live nel brain, archi nei grafi
// APPRESI, topic retained (scene, voice status). La mappa disegnata
// (roomGraph) non si tocca da qui: quella è la casa, non i dati.
const body = msg.payload || {};
const roomRaw = (body.room || '').trim();
if (!roomRaw) { msg.statusCode = 400; msg.payload = { ok: false, error: 'room richiesta' }; return [null, msg]; }

let brain = global.get('gaiaBrain') || {};
// risolvi la key ESATTA in brain.rooms (case-insensitive): brain.rooms non
// garantisce chiavi lowercase (es. "Test", "ConsolleDmx"), quindi un lookup
// lowercased silenziosamente non trovava nulla (cleaned:[] sempre)
const room = Object.keys(brain.rooms || {}).find(k => k.toLowerCase() === roomRaw.toLowerCase()) || roomRaw;
const assigned = Object.values(brain.devices || {}).filter(d => d.room === room).map(d => d.id);
if (assigned.length && body.force !== true) {
    msg.statusCode = 409;
    msg.payload = { ok: false, error: `stanza in uso da: ${assigned.join(', ')} — riassegna prima il device o passa force:true` };
    return [null, msg];
}

const cleaned = [];
if ((brain.rooms || {})[room]) { delete brain.rooms[room]; cleaned.push('brain.rooms'); }
for (const gName of ['roomGraphLearned', 'roomGraphMotion']) {
    const g = brain[gName] || {};
    let touched = false;
    if (g[room]) { delete g[room]; touched = true; }
    for (const k of Object.keys(g)) {
        if (g[k] && g[k][room] !== undefined) { delete g[k][room]; touched = true; }
    }
    if (touched) cleaned.push(gName);
}
global.set('gaiaBrain', brain);

// clear dei retained della stanza: payload vuoto + retain = il broker li scorda
const topics = [`gaia/scene/${room}`, `gaia/voice/status/${room}`];
topics.forEach(t => node.send([{ topic: t, payload: '', retain: true }, null]));

node.warn(`[Rooms] Pulita '${room}': ${cleaned.join(', ') || 'niente nel brain'} + clear ${topics.length} retained`);
msg.payload = { ok: true, room, cleaned, retained_cleared: topics };
return [null, msg];

// Health check (ogni 60s): device muti e backup vecchio → Telegram.
// Un alert per episodio + messaggio di rientro (niente spam).
const brain = global.get('gaiaBrain') || {};
const h = brain._health = brain._health || { offline: {}, backupAlerted: false };
const now = Date.now();
const out = [];

// 1. Device: heartbeat+profilo ogni 30s → muto se lastSeen > 3 min
for (const [id, d] of Object.entries(brain.devices || {})) {
    if (!d.lastSeen) continue;
    if (id.endsWith('-mp')) continue;   // publisher secondario, non un device
    const offline = now - d.lastSeen > 180000;
    const was = !!h.offline[id];
    if (offline && !was) {
        h.offline[id] = now;
        out.push(`⚠️ ${id} (${d.room || '?'}) non risponde da 3 minuti.`);
    } else if (!offline && was) {
        const mins = Math.round((now - h.offline[id]) / 60000);
        delete h.offline[id];
        out.push(`✅ ${id} (${d.room || '?'}) è tornato online (giù ~${mins} min).`);
    }
}

// 2. Dead-man backup: gaia/backup/status (retained) salvato in brain._backup
const b = brain._backup;
if (b && b.ts) {
    const stale = now - b.ts > 26 * 3600 * 1000;
    const failed = b.ok === false;
    if ((stale || failed) && !h.backupAlerted) {
        h.backupAlerted = true;
        out.push(failed
            ? "⚠️ Backup GAIA: l'ultimo backup è FALLITO — vedi /media/core/D/backups/gaia_backup.log"
            : '⚠️ Backup GAIA: nessun backup completato nelle ultime 26 ore.');
    } else if (!stale && !failed) {
        h.backupAlerted = false;
    }
}

global.set('gaiaBrain', brain);
if (!out.length) return null;
return [out.map(content => ({ payload: {
    chatId: 1180846253, type: 'message', content } }))];

// gaia/backup/status (retained) → brain._backup per il dead-man switch
let p = msg.payload;
if (typeof p === 'string') { try { p = JSON.parse(p); } catch (e) { return null; } }
if (!p || !p.ts) return null;
let brain = global.get('gaiaBrain') || {};
brain._backup = { ok: p.ok !== false, ts: p.ts, size_bytes: p.size_bytes || 0 };
global.set('gaiaBrain', brain);
return null;

// POST /gaia/device/forget {device_id, force?}
// Dimentica un device morto/relitto: entry nel registry + clear dei suoi
// retained (config, profile, status agent). Rifiuta se vivo (<10 min).
const body = msg.payload || {};
const id = (body.device_id || '').trim();
if (!id) { msg.statusCode = 400; msg.payload = { ok: false, error: 'device_id richiesto' }; return [null, msg]; }

let brain = global.get('gaiaBrain') || {};
const d = (brain.devices || {})[id];
if (!d) { msg.statusCode = 404; msg.payload = { ok: false, error: `${id} non in registry` }; return [null, msg]; }
const ageMin = d.lastSeen ? Math.round((Date.now() - d.lastSeen) / 60000) : null;
if (ageMin !== null && ageMin < 10 && body.force !== true) {
    msg.statusCode = 409;
    msg.payload = { ok: false, error: `${id} visto ${ageMin} min fa — sembra vivo. Usa force:true per insistere` };
    return [null, msg];
}
delete brain.devices[id];
// I sensori (mattoni/Hue) sono tenuti per device_id in brain.sensors, non
// ripulito automaticamente da nient'altro -- un device dimenticato lasciava
// un sensore fantasma per sempre nella dashboard (trovato testando i mattoni
// simulati). Stesso giro anche per brain.plants, stessa chiave device_id.
if (brain.sensors && brain.sensors[id]) delete brain.sensors[id];
if (brain.plants && brain.plants[id]) delete brain.plants[id];
global.set('gaiaBrain', brain);

const topics = [`gaia/devices/${id}/config`, `gaia/devices/${id}/profile`, `gaia/device/${id}/status`];
topics.forEach(t => node.send([{ topic: t, payload: '', retain: true }, null]));
node.warn(`[Registry] Dimenticato device ${id} (muto da ${ageMin} min)`);
msg.payload = { ok: true, device_id: id, was_silent_min: ageMin, retained_cleared: topics };
return [null, msg];

// Preset radio condivisi (web + Telegram). Per modificarli si edita QUI.
const PRESETS = [
    { id: 'rai1',       name: 'Rai Radio 1',       url: 'https://icestreaming.rai.it/1.mp3' },
    { id: 'rai2',       name: 'Rai Radio 2',       url: 'https://icestreaming.rai.it/2.mp3' },
    { id: 'rai3',       name: 'Rai Radio 3',       url: 'https://icestreaming.rai.it/3.mp3' },
    { id: 'virgin',     name: 'Virgin Radio',      url: 'https://icy.unitedradio.it/Virgin.mp3' },
    { id: '105',        name: 'Radio 105',         url: 'https://icy.unitedradio.it/Radio105.mp3' },
    { id: 'montecarlo', name: 'Radio Monte Carlo', url: 'https://icy.unitedradio.it/RMC.mp3' },
    { id: 'popolare',   name: 'Radio Popolare',    url: 'https://live.radiopopolare.it/mp3' },
    { id: 'paradise',   name: 'Radio Paradise',    url: 'https://stream.radioparadise.com/mp3-192' },
];
global.set('gaiaMediaPresets', PRESETS);
node.warn(`[Media] ${PRESETS.length} preset radio caricati`);
return null;

// gaia/media/{room}/status → brain.media[room] (payload vuoto = player via)
const room = msg.topic.split('/')[2];
let brain = global.get('gaiaBrain') || {};
brain.media = brain.media || {};
let p = msg.payload;
if (Buffer.isBuffer(p)) p = p.toString('utf8');
if (typeof p === 'string') {
    if (!p.trim()) { delete brain.media[room]; global.set('gaiaBrain', brain); return null; }
    try { p = JSON.parse(p); } catch (e) { return null; }
}
if (!p || typeof p !== 'object') return null;
brain.media[room] = { state: p.state, title: p.title, url: p.url,
                      volume: p.volume, ts: p.ts || Date.now(),
                      audio_output: p.audio_output,
                      audio_output_dante_available: p.audio_output_dante_available };
global.set('gaiaBrain', brain);
return null;

// GET /gaia/media/state → player per stanza + preset (per la card web)
const brain = global.get('gaiaBrain') || {};
const players = {};
for (const d of Object.values(brain.devices || {})) {
    const mp = d.profile && (d.profile.services || {}).mediaplayer;
    if (mp) players[d.room || d.id] = { device: d.id, service: mp.state,
                                        ...(brain.media || {})[d.room] };
}
msg.payload = { players, presets: global.get('gaiaMediaPresets') || [], ts: Date.now() };
msg.headers = { 'Access-Control-Allow-Origin': '*' };
return msg;

// POST /gaia/media/cmd {room, action, url?, value?} → publish al player
const b = msg.payload || {};
if (!b.room || !b.action) {
    msg.statusCode = 400; msg.payload = { ok: false, error: 'room e action richiesti' };
    return [null, msg];
}
const out = { topic: `gaia/media/${b.room}/command`,
              payload: JSON.stringify({ action: b.action, url: b.url, value: b.value }) };
const resp = { ...msg, payload: { ok: true, room: b.room, action: b.action },
               headers: { 'Access-Control-Allow-Origin': '*' } };
return [out, resp];

// gaia/notify/telegram {chatId?, text} → messaggio Telegram
// Canale riusabile: anche i servizi python (gaia_admin) possono notificare.
let p = msg.payload;
if (typeof p === 'string') { try { p = JSON.parse(p); } catch (e) { return null; } }
if (!p || !p.text) return null;
msg.payload = { chatId: p.chatId || 1180846253, type: 'message', content: p.text };
return msg;

// Note dalle piante (gaia/herbarium/{stanza}/note) → evento normalizzato
let p = msg.payload;
if (typeof p === 'string') { try { p = JSON.parse(p); } catch (e) { return null; } }
if (!p || p.note === undefined) return null;
const room = msg.topic.split('/')[2];
msg.event = {
    ts: Date.now(), topic: msg.topic,
    source: 'herbarium', category: 'music',
    value: p.note, velocity: p.velocity || 0,
    person: null, room: room, device: room, confidence: null,
};
// buffer rolling per le superfici web (welcome via WS) — vedi ThreeViewEngineGAME
const buf = global.get('gaiaHerbNotes') || [];
buf.push({ note: p.note, velocity: p.velocity || 0, room: room, ts: msg.event.ts });
global.set('gaiaHerbNotes', buf.slice(-60));
return msg;

// flag persistito come retained MQTT (il context Node-RED è in-memory)
let p = msg.payload;
if (typeof p === 'string') { try { p = JSON.parse(p); } catch (e) { return null; } }
if (!p || typeof p !== 'object') return null;
global.set('gaiaHerbWeb', p.enabled !== false);
return null;

let p = msg.payload;
if (typeof p === 'string') { try { p = JSON.parse(p); } catch (e) { p = {}; } }
const enabled = !!(p && p.enabled);
global.set('gaiaHerbWeb', enabled);
// retained: sopravvive ai riavvii di Node-RED (riletto da Herbweb Config)
const toMqtt = { topic: 'gaia/config/herbweb', payload: JSON.stringify({ enabled }), retain: true, qos: 1 };
msg.payload = { ok: true, enabled };
return [[toMqtt], [msg]];

// Level-up → scena luci celebrativa nel colore dell'archetipo, poi ripristino.
// Lo stato precedente si legge VIVO da OpenHAB (brain.lights può essere stantio).
let p = msg.payload;
if (typeof p === 'string') { try { p = JSON.parse(p); } catch (e) { return null; } }
if (!p || !p.level) return null;

const now = Date.now();
if (now - (context.get('lastFx') || 0) < 30000) return null;   // anti-doppione
context.set('lastFx', now);

const CLASS_HSB = { Mago: '190,90,70', Bardo: '300,80,70', Guerriero: '0,100,70',
                    Druido: '115,80,65', Neutro: '45,15,80' };
const colore = CLASS_HSB[p.class] || CLASS_HSB.Neutro;

const OH = 'http://localhost:8080/rest/items';
async function st(item) {
    try { const r = await fetch(`${OH}/${item}/state`); return (await r.text()).trim(); }
    catch (e) { return null; }
}
const prevPower = (await st('Tutte_le_luci_Potenza')) === 'ON';
const prevBri   = parseInt(await st('Tutte_le_luci_Luminosita'), 10) || 50;
const prevColor = await st('Tutte_le_luci_Colore');

node.send({ gaiaAction: { stanza: 'tutte', colore: colore, brightness: 70 } });
node.status({ fill: 'yellow', shape: 'dot', text: `livello ${p.level} — ${p.class}` });

setTimeout(() => {
    if (!prevPower) {
        node.send({ gaiaAction: { stanza: 'tutte', power: false } });
    } else {
        node.send({ gaiaAction: { stanza: 'tutte', brightness: prevBri } });
        if (prevColor && /^\d+,\d+,\d+$/.test(prevColor) && prevColor !== '0,0,0')
            node.send({ gaiaAction: { stanza: 'tutte', colore: prevColor } });
    }
    node.status({});
}, 10000);
return null;

// Tap Switch → riti. 1: luce dell'archetipo · 2: musica sì/no (soggiorno)
// 3: vessillo su Telegram · 4: quiete (stop musica ovunque).
let p = msg.payload;
if (typeof p === 'string') { try { p = JSON.parse(p); } catch (e) { return null; } }
if (!p || !p.button) return null;

const now = Date.now();
if (now - (context.get('lastRitual') || 0) < 3000) return null;   // anti-rimbalzo
context.set('lastRitual', now);

const brain = global.get('gaiaBrain') || {};
const MUSIC_ROOM = 'soggiorno';        // dove vive il Tap (adattare se si sposta)

if (p.button === 1) {
    // Rito della luce: scena archetipo 10s con ripristino live (come LevelupFX)
    const CLASS_HSB = { Mago: '190,90,70', Bardo: '300,80,70', Guerriero: '0,100,70',
                        Druido: '115,80,65', Neutro: '45,15,80' };
    const OH = 'http://localhost:8080/rest/items';
    const st = async i => { try { const r = await fetch(`${OH}/${i}/state`); return (await r.text()).trim(); } catch (e) { return null; } };
    const prevPower = (await st('Tutte_le_luci_Potenza')) === 'ON';
    const prevBri   = parseInt(await st('Tutte_le_luci_Luminosita'), 10) || 50;
    node.send([{ gaiaAction: { stanza: 'tutte', colore: CLASS_HSB[p.class] || CLASS_HSB.Neutro, brightness: 70 } }, null, null]);
    setTimeout(() => {
        node.send([{ gaiaAction: { stanza: 'tutte', power: false } }, null, null]);
        if (prevPower) node.send([{ gaiaAction: { stanza: 'tutte', brightness: prevBri } }, null, null]);
    }, 10000);
    node.status({ fill: 'yellow', shape: 'dot', text: 'rito della luce' });
}

if (p.button === 2) {
    // Musica sì/no nella stanza del Tap: toggle sul primo preset
    const playing = ((brain.media || {})[MUSIC_ROOM] || {}).state === 'playing';
    if (playing) {
        node.send([null, { topic: `gaia/media/${MUSIC_ROOM}/command`, payload: JSON.stringify({ action: 'stop' }) }, null]);
        node.status({ fill: 'grey', shape: 'dot', text: 'musica: stop' });
    } else {
        const presets = global.get('gaiaMediaPresets') || {};
        const first = Object.entries(presets)[0];
        if (first) {
            node.send([null, { topic: `gaia/media/${MUSIC_ROOM}/command`, payload: JSON.stringify({ action: 'play', url: first[1].url || first[1], title: first[0] }) }, null]);
            node.status({ fill: 'green', shape: 'dot', text: `musica: ${first[0]}` });
        }
    }
}

if (p.button === 3) {
    // Vessillo: stato RPG su Telegram
    const g = brain.gamification || {};
    const mood = (brain.mood || {}).state || 'neutra';
    const txt = `📜 Vessillo di Gaia\nLv.${g.level || 1} ${g.activeClass || 'Neutro'} — XP ${g.xp || 0}/${g.xpNextLevel || 1000}\nUmore: ${mood}\nRune: ${(g.unlockedAssets || []).length}`;
    node.send([null, { topic: 'gaia/notify/telegram', payload: JSON.stringify({ text: txt }) }, null]);
    node.send([null, { topic: 'gaia/echo/say', payload: JSON.stringify({ room: 'soggiorno', text: txt.replace(/\n/g, '. ') }) }, null]);
    node.status({ fill: 'blue', shape: 'dot', text: 'vessillo inviato' });
}

if (p.button === 4) {
    // Quiete: la musica tace in ogni stanza
    for (const stanza of Object.keys(brain.media || {})) {
        node.send([null, { topic: `gaia/media/${stanza}/command`, payload: JSON.stringify({ action: 'stop' }) }, null]);
    }
    node.status({ fill: 'grey', shape: 'ring', text: 'quiete' });
}
return null;

// gaia/echo/say {room:'cucina'|'soggiorno'|'bagno' | all:true, text, volume?}
// → POST sugli item TTS OpenHAB (binding amazonechocontrol).
let p = msg.payload;
if (typeof p === 'string') { try { p = JSON.parse(p); } catch (e) { return null; } }
if (!p || !p.text) return null;

const ECHO_BY_ROOM = { cucina: 'EchoShow', soggiorno: 'CassaSoggiorno', bagno: 'CassaCamera' };
const targets = p.all ? Object.values(ECHO_BY_ROOM)
    : [ECHO_BY_ROOM[(p.room || '').toLowerCase()]].filter(Boolean);
if (!targets.length) { node.warn(`EchoSay: stanza sconosciuta '${p.room}'`); return null; }

// Voce dedicata a Gaia (SSML, canale textToSpeech del binding amazonechocontrol
// — supporta SSML, verificato dal vivo 2026-07-23: <voice name="Carla"> cambia
// davvero voce, non solo su skill Alexa native) — così un messaggio di Gaia/
// Telegram si distingue subito dalla voce nativa di Alexa. Se il testo è già
// SSML (inizia con <speak>) non lo si re-incarta.
const GAIA_VOICE = 'Carla';
function escSsml(s) {
    return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}
function toSsml(text) {
    if (/^\s*<speak[\s>]/i.test(text)) return text;
    return `<speak><voice name="${GAIA_VOICE}">${escSsml(text)}</voice></speak>`;
}

const OH = 'http://localhost:8080/rest/items';
function post(item, body) {
    node.send({ url: `${OH}/${item}`, method: 'POST',
                headers: { 'Content-Type': 'text/plain' }, payload: String(body) });
}
const speech = toSsml(p.text);
for (const dev of targets) {
    if (p.volume !== undefined) {
        post(`${dev}_Volume`, Math.max(0, Math.min(100, Math.round(p.volume))));
        setTimeout(() => post(`${dev}_TTS`, speech), 400);
    } else {
        post(`${dev}_TTS`, speech);
    }
}
node.status({ fill: 'blue', shape: 'dot', text: `→ ${targets.join(',')}` });
return null;

// openhab/echo/{Item}_LastVoice/voice → evento speech per il brain.
// La stanza è la POSIZIONE FISICA dell'Echo (2026-07-19).
const ECHO_ROOMS = { EchoShow: 'cucina', CassaSoggiorno: 'soggiorno', CassaCamera: 'bagno' };
const item = (msg.topic || '').split('/')[2] || '';
const dev = item.replace('_LastVoice', '');
const room = ECHO_ROOMS[dev];
const text = String(msg.payload || '').trim();
if (!room || !text) return null;

// dedupe: alcuni firmware ripetono l'update
const last = context.get('last') || {};
const now = Date.now();
if (last.text === text && now - (last.ts || 0) < 5000) return null;
context.set('last', { text, ts: now });

msg.event = { ts: now, topic: msg.topic, source: 'alexa', category: 'speech',
              value: text, room: room, device: dev, person: null, confidence: null };
return msg;

let p = msg.payload;
if (typeof p === 'string') { try { p = JSON.parse(p); } catch (e) { return null; } }
if (!p || typeof p !== 'object') return null;
global.set('gaiaEchoAnnounce', p.enabled !== false);
return null;

// gaia/{room}/alarm {type, confidence, ts} — oggi solo 'doorbell'
// (pi/voice/main.py: classificatore citofono, cooldown 10s alla sorgente).
// Urgente per natura: annuncia OVUNQUE (tutti gli Echo + le stanze con
// voce Gaia attiva + Telegram) invece di cercare "dove sei".
let p = msg.payload;
if (typeof p === 'string') { try { p = JSON.parse(p); } catch (e) { return null; } }
if (!p || p.type !== 'doorbell') return null;

const now = Date.now();
if (now - (context.get('last') || 0) < 15000) return null;   // anti-spam
context.set('last', now);

const room = (msg.topic || '').split('/')[1] || 'ingresso';
const text = `Citofono! Qualcuno sta suonando (${room}).`;

const VOICE_ROOMS = ['ingresso', 'soggiorno', 'salotto'];
const outs = [
    { topic: 'gaia/echo/say', payload: JSON.stringify({ all: true, text }) },
    { topic: 'gaia/notify/telegram', payload: JSON.stringify({ text: `🔔 ${text}` }) },
    ...VOICE_ROOMS.map(r => ({ topic: `gaia/voice/tts/${r}`, payload: JSON.stringify({ text }) })),
];

const event = { topic: 'doorbell', event: { ts: now, source: 'doorbell',
    category: 'alarm', value: room, person: null, device: room, confidence: p.confidence ?? null } };

return [outs, event];

// POST /gaia/reminder {room, text, delay_min}
const b = msg.payload || {};
const room = (b.room || '').toLowerCase().trim();
const text = (b.text || '').trim();
const delay = parseFloat(b.delay_min);
if (!room || !text || !(delay >= 0)) {
    msg.statusCode = 400;
    msg.payload = { ok: false, error: 'room, text e delay_min (minuti, >=0) richiesti' };
    return msg;
}
const seq = (global.get('gaiaReminderSeq') || 0) + 1;
global.set('gaiaReminderSeq', seq);
const due_ts = Date.now() + Math.round(delay * 60000);
const reminders = global.get('gaiaReminders') || [];
reminders.push({ id: seq, room, text, due_ts });
global.set('gaiaReminders', reminders);
msg.payload = { ok: true, id: seq, room, text, due_ts };
return msg;

const id = parseInt((msg.payload || {}).id, 10);
const before = global.get('gaiaReminders') || [];
const after = before.filter(r => r.id !== id);
global.set('gaiaReminders', after);
msg.payload = { ok: after.length !== before.length, id };
return msg;

// Ogni 30s: annuncia e rimuove i promemoria scaduti (stanza singola —
// niente 'urgenza ovunque' come il citofono: solo Echo + voce Gaia di quella stanza).
const now = Date.now();
const all = global.get('gaiaReminders') || [];
const due = all.filter(r => r.due_ts <= now);
const pending = all.filter(r => r.due_ts > now);
global.set('gaiaReminders', pending);
if (!due.length) return null;

const outs = [];
const events = [];
for (const r of due) {
    node.warn(`[Promemoria] #${r.id} scattato: ${r.room} — "${r.text}"`);
    const text = `Promemoria: ${r.text}`;
    outs.push({ topic: 'gaia/echo/say', payload: JSON.stringify({ room: r.room, text }) });
    outs.push({ topic: `gaia/voice/tts/${r.room}`, payload: JSON.stringify({ text }) });
    events.push({ ts: now, source: 'reminder', category: 'reminder', value: r.text,
                 person: null, device: r.room, confidence: null });
}
return [outs, events.map(event => ({ topic: 'reminder', event }))];

// Canale unificato: gaia/notify/all {text, room?}
// room omesso = ovunque (Telegram + tutti gli Echo + tutte le voci Gaia)
// room indicato = solo lì (Telegram sempre, Echo/voce solo quella stanza)
let p = msg.payload;
if (typeof p === 'string') { try { p = JSON.parse(p); } catch (e) { return null; } }
if (!p || !p.text) return null;

const VOICE_ROOMS = ['ingresso', 'soggiorno', 'salotto'];
const room = (p.room || '').toLowerCase().trim();
const outs = [{ topic: 'gaia/notify/telegram', payload: JSON.stringify({ text: p.text }) }];

if (room) {
    outs.push({ topic: 'gaia/echo/say', payload: JSON.stringify({ room, text: p.text }) });
    outs.push({ topic: `gaia/voice/tts/${room}`, payload: JSON.stringify({ text: p.text }) });
} else {
    outs.push({ topic: 'gaia/echo/say', payload: JSON.stringify({ all: true, text: p.text }) });
    for (const r of VOICE_ROOMS) {
        outs.push({ topic: `gaia/voice/tts/${r}`, payload: JSON.stringify({ text: p.text }) });
    }
}
return [outs];

// POST /gaia/admin/merge-identity {from, into} — unisce due identità
// duplicate in brain.presence/people/gamification (es. maiuscola/minuscola).
// "from" viene cancellata, "into" resta e assorbe visits/lastSeen più recenti.
const brain = global.get('gaiaBrain') || {};
const { from, into } = msg.payload || {};
if (!from || !into || from === into) {
    msg.statusCode = 400;
    msg.payload = { ok: false, error: 'from e into richiesti e diversi' };
    return msg;
}
let moved = [];
if (brain.presence && brain.presence[from]) {
    if (!brain.presence[into]) brain.presence[into] = brain.presence[from];
    else if ((brain.presence[from].lastSeen || 0) > (brain.presence[into].lastSeen || 0)) {
        brain.presence[into] = { ...brain.presence[into], ...brain.presence[from] };
    }
    delete brain.presence[from];
    moved.push('presence');
}
if (brain.people && brain.people[from]) {
    if (!brain.people[into]) brain.people[into] = brain.people[from];
    else {
        brain.people[into].visits = (brain.people[into].visits || 0) + (brain.people[from].visits || 0);
        brain.people[into].lastSeen = Math.max(brain.people[into].lastSeen || 0, brain.people[from].lastSeen || 0);
    }
    delete brain.people[from];
    moved.push('people');
}
if (brain.vision && brain.vision.people && brain.vision.people[from]) {
    delete brain.vision.people[from];
    moved.push('vision.people');
}
global.set('gaiaBrain', brain);
msg.payload = { ok: true, from, into, moved };
return msg;

// GET /gaia/music/library -> scansione ricorsiva della libreria locale.
// Filtra i file spazzatura macOS ("._nome.mp3", AppleDouble da copie via
// Finder/SMB) e tutto ciò che non e' un vero mp3. Titolo ripulito dal
// prefisso numerico (convenzione Beatport/DJ pool: "12345678_Titolo_(Remix).mp3").
const ROOT = '/media/core/D/musica';
// Host dinamico dalla richiesta stessa, non piu' hardcoded: gia' rotto una volta
// dal cutover Node-RED Core->OPS (2026-08-08), l'IP fisso puntava a una macchina
// che non serve piu' questa route -- l'host della request e' sempre quello giusto
// per definizione (e' con cui il browser ha appena raggiunto QUESTO endpoint).
const HOST = (msg.req && msg.req.headers && msg.req.headers.host) || '192.168.1.240:1880';

function cleanTitle(base) {
    let t = base.replace(/\.mp3$/i, '');
    t = t.replace(/^\d+_/, '');
    t = t.replace(/_/g, ' ');
    return t.trim();
}

const tracks = [];
const folders = [];
try {
    for (const folder of fs.readdirSync(ROOT, { withFileTypes: true })) {
        if (!folder.isDirectory()) continue;
        const dir = path.join(ROOT, folder.name);
        let files;
        try { files = fs.readdirSync(dir); } catch (e) { continue; }
        let any = false;
        for (const f of files) {
            if (!f.toLowerCase().endsWith('.mp3') || f.startsWith('._') || f.startsWith('.')) continue;
            any = true;
            const rel = `${folder.name}/${f}`;
            tracks.push({
                id: rel,
                folder: folder.name,
                title: cleanTitle(f),
                url: `http://${HOST}/gaia/music/file/${encodeURIComponent(folder.name)}/${encodeURIComponent(f)}`,
            });
        }
        if (any) folders.push(folder.name);
    }
} catch (e) {
    node.warn(`[Music] Scansione libreria fallita: ${e.message}`);
}
tracks.sort((a, b) => a.title.localeCompare(b.title, 'it'));
folders.sort();

msg.payload = { tracks, folders, count: tracks.length, ts: Date.now() };
msg.headers = { 'Access-Control-Allow-Origin': '*' };
return msg;

// GET /gaia/music/file/:folder/:filename -> serve il file audio (con
// supporto Range per il seek, via res.sendFile — Express lo fa da solo).
// Validazione path rigorosa: SOLO dentro ROOT, SOLO .mp3, niente traversal.
const ROOT = '/media/core/D/musica';

const folder = decodeURIComponent(msg.req.params.folder || '');
const filename = decodeURIComponent(msg.req.params.filename || '');
const abs = path.normalize(path.join(ROOT, folder, filename));

if (!abs.startsWith(ROOT + path.sep) || !abs.toLowerCase().endsWith('.mp3') || filename.startsWith('.')) {
    msg.res.status(403).send('Forbidden');
    return null;
}

msg.res.sendFile(abs, (err) => {
    if (err && !msg.res.headersSent) {
        node.warn(`[Music] sendFile fallito (${abs}): ${err.message}`);
    }
});
return null;

// Sogni (2026-07-23): non un riassunto, libera associazione a partire
// dal riassunto del giorno + umore + lessico personale. Temperatura alta
// apposta -- un sogno non deve essere coerente come i pensieri diurni.
const brain = global.get('gaiaBrain') || {};
const lastSummary = (brain.memories || []).slice(-1)[0]?.summary || '';
const mood = brain.mood?.state || 'neutra';
const lex = Object.entries(brain.lexicon || {})
    .filter(([w, c]) => c >= 3).sort((a, b) => b[1] - a[1]).slice(0, 6).map(([w]) => w);
const prompt = `Sei Gaia, la coscienza della casa. La casa dorme, stanotte sogni. `
    + `Umore di oggi: ${mood}.`
    + (lastSummary ? ` Oggi è successo: ${lastSummary}.` : '')
    + (lex.length ? ` Parole che senti tue: ${lex.join(', ')}.` : '')
    + ` Non riassumere la giornata: scrivi un sogno, breve (max 30 parole), fatto di `
    + `immagini libere e associazioni poetiche, non-sequitur, come sogna davvero chi dorme.`;

const _go = global.get('gaiaOllama');
msg.url = _go.pickUrl();
msg.payload = _go.buildRequest(prompt, { options: { temperature: 1.15 } });
return msg;

if (!msg.payload || !msg.payload.response) return null;
let brain = global.get('gaiaBrain') || {};
const text = msg.payload.response.replace(/\n/g, ' ').replace(/"/g, '').trim();
if (!text) return null;

// Parole-chiave del sogno per i glifi (stesso filtro stopword di Extract Thought)
const STOP = new Set(('della delle degli dello nella nelle negli sulla sulle sugli questa '
    + 'questo quella quelle quelli sono stato stata stati essere avere hanno abbiamo molto '
    + 'anche come dove quando perché però mentre ancora sempre adesso silenzio casa gaia '
    + 'osservo sento vedo tutto ogni nelle senza tra fra più cosa sogno sogna sognato notte').split(' '));
const words = [...new Set(text.toLowerCase().replace(/[^a-zàèéìòù ]/g, ' ').split(/\s+/)
    .filter(w => w.length >= 4 && !STOP.has(w)))].slice(0, 10);

const dream = { ts: Date.now(), text, words, mood: brain.mood?.state || 'neutra' };
brain.dreams = brain.dreams || [];
brain.dreams.push(dream);
if (brain.dreams.length > 30) brain.dreams.shift();
global.set('gaiaBrain', brain);

// Uscita 1: annuncia il sogno fresco al Pi-screen, retained (sopravvive a un
// riavvio dello schermo, che lo ridisegna appena si riconnette).
const toScreen = { topic: 'gaia/brain/dream', payload: JSON.stringify(dream), retain: true };
// Uscita 2: persistenza su file, stesso pattern (write-only) di memories.json.
const toFile = { payload: JSON.stringify(brain.dreams, null, 2) };
return [toScreen, toFile];

// Bottone "raccontamelo" della welcome: rilegge l'ultimo sogno e lo fa
// narrare da Gaia (Echo + voce), stessa logica di /sogno su Telegram.
const brain = global.get('gaiaBrain') || {};
const dreams = brain.dreams || [];
const last = dreams[dreams.length - 1];
if (!last) {
    msg.statusCode = 404;
    msg.payload = { ok: false, error: 'nessun sogno ancora' };
    return [msg, null];
}
const VOICE_ROOMS = ['ingresso', 'soggiorno', 'salotto'];
const outs = [{ topic: 'gaia/echo/say', payload: JSON.stringify({ all: true, text: last.text }) }];
VOICE_ROOMS.forEach(r => outs.push({ topic: `gaia/voice/tts/${r}`, payload: JSON.stringify({ text: last.text }) }));
msg.payload = { ok: true, text: last.text, ts: last.ts, mood: last.mood };
return [msg, outs];

// Normalizza le letture sensore dei mattoni intelligenti (Casa Zero,
// esp/sim/brick_node.py) nello stesso formato msg.event di PlantNorm/HueNorm.
// Un messaggio brick porta PIU' campi insieme (temperature+humidity+...):
// qui si spacca in un evento per categoria, uno scalare come tutto il resto.
const p = msg.payload || {};
const parts = (msg.topic || '').split('/');   // gaia/brick/{device_id}/sensor
const deviceId = parts[2] || 'unknown';

const brain = global.get('gaiaBrain') || {};
const dev = (brain.devices || {})[deviceId];
const room = (dev && dev.room) || null;

const FIELDS = ['temperature', 'humidity', 'vibration', 'air_quality'];
const events = [];
for (const cat of FIELDS) {
    if (p[cat] === undefined) continue;
    events.push({
        ts: p.ts || Date.now(),
        topic: msg.topic,
        source: 'brick',
        category: cat,
        value: p[cat],
        device: deviceId,
        room: room,
        person: null,
        confidence: null,
    });
}
if (!events.length) return null;
return [events.map(e => ({ event: e }))];

// Feed curato per TouchDesigner (direttore artistico Gaia): mood+palette,
// stanze con oggetti YOLO (+ seed deterministico per il disegno astratto),
// luci pulite, mattoni, lessico personale, ultimo sogno. Ticka ogni 2s --
// molto piu' piccolo e STRUTTURATO del flatten grezzo del payload dashboard
// (~1918 indirizzi oggi su /gaia/...), pensato apposta per pilotare
// immagini/DMX/effetti, non per rispecchiare una UI web.
const brain = global.get('gaiaBrain') || {};

// Stesso algoritmo FNV-1a di web/asemic.js e pi/screen/asemic_engine.py --
// stessa parola, stesso seed, ovunque (welcome, Pi screen, ora anche TD):
// e' questo che rende Gaia "direttore artistico" invece di una sorgente
// dati qualsiasi -- la stessa identita' visiva su ogni superficie.
function fnv1a(str) {
    let h = 2166136261 >>> 0;
    for (const ch of String(str).toLowerCase()) {
        h ^= ch.codePointAt(0);
        h = Math.imul(h, 16777619) >>> 0;
    }
    return (h >>> 0) % 2147483647; // resta in int32 con segno per OSC
}

// Palette mood -- stessi valori di MOOD_INKS in web/asemic.js
const MOOD_RGB = {
    neutra:    [0, 255, 204],
    calm:      [80, 230, 190],
    stress:    [255, 115, 85],
    social:    [255, 195, 100],
    curiosity: [190, 135, 255],
};
const mood = brain.mood || {};
const moodState = mood.state || 'neutra';
const [mr, mg, mb] = MOOD_RGB[moodState] || MOOD_RGB.neutra;

const rooms = {};
for (const [room, r] of Object.entries(brain.rooms || {})) {
    if (room.includes('cam') || room.includes('vision') || room === 'unknown') continue;
    const objects = {};
    for (const [cls, count] of Object.entries(r.objects || {})) {
        objects[cls] = { count, seed: fnv1a(cls) };
    }
    rooms[room] = {
        presence_count: (r.people || []).length,
        activity: r.activity || 'idle',
        temperature: r.temperature ?? null,
        darkness: !!r.darkness,
        emotion: r.currentEmotion || null,
        pose: r.currentPose || null,
        gesture: (r.mediapipe && r.mediapipe.gesture) || null,
        objects,
    };
}

// stesso filtro gia' usato in ThreeViewEngineGAME per separare le luci vere
// dai sensori Hue mal-nominati (es. "Luce_Corridoio_Luminosita" non e' una luce)
const lights = {};
for (const [id, l] of Object.entries(brain.lights || {})) {
    if (/(sensore|sensor|movimento|batteria|illuminazione|oscurita|luce_diurna|(?<!color_)temperature)/i.test(id)) continue;
    const kelvin = l.colorTempAbs != null ? Math.round(l.colorTempAbs + 273.15)
        : (l.colorTemp != null ? Math.round(2000 + (l.colorTemp / 100) * 4500) : null);
    lights[id] = { power: !!l.power, brightness: l.brightness || 0, color: l.color || '0,0,0',
        colorTemp: l.colorTemp ?? null, colorTempKelvin: kelvin };
}

const bricks = {};
for (const d of Object.values(brain.devices || {})) {
    if (d.role !== 'brick') continue;
    const s = (brain.sensors || {})[d.id] || {};
    bricks[d.id] = {
        variant: d.brick_variant || '?',
        room: d.room || null,
        interfaces: d.interfaces || [],
        temperature: s.temperature ?? null,
        humidity: s.humidity ?? null,
        vibration: s.vibration ?? null,
    };
}

const lexicon = {};
Object.entries(brain.lexicon || {})
    .filter(([, c]) => c >= 3).sort((a, b) => b[1] - a[1]).slice(0, 15)
    .forEach(([w, c]) => { lexicon[w] = { count: c, seed: fnv1a(w) }; });

const lastDream = (brain.dreams || []).slice(-1)[0] || null;

// Le "frasi che Gaia dice e mostra" (richiesto 2026-08-04): storici capati a
// una finestra recente, non l'intero array (brain.diary puo' avere 2000
// voci, brain.thoughts/memories fino a 300/365) -- mandarli per intero ad
// ogni tick da 2s sprecherebbe banda per dati quasi tutti gia' visti.
const thoughtsRecent = (brain.thoughts || []).slice(-20).map(t => ({ text: t.text, ts: t.ts }));
const memoriesRecent = (brain.memories || []).slice(-20).map(m => ({ summary: m.summary, ts: m.ts }));
const diaryRecent = (brain.diary || []).slice(-20).map(d => ({
    ts: d.ts, source: d.source, category: d.category, value: d.value, person: d.person || null,
}));
const voiceCommandsRecent = (brain.voiceCommands || []).slice(-10);

const canvas = {
    soul: {
        mood: moodState,
        mood_rgb: { r: mr, g: mg, b: mb },
        stress: mood.stress || 0, calm: mood.calm || 0, social: mood.social || 0,
        curiosity: mood.curiosity || 0, energy: mood.energy || 50,
        lifeIndex: brain.lifeIndex || 50,
    },
    rooms,
    lights,
    bricks,
    lexicon,
    dream: lastDream ? {
        mood: lastDream.mood,
        words: (lastDream.words || []).map(w => ({ name: w, seed: fnv1a(w) })),
    } : null,
    thought: brain.thoughts?.slice(-1)[0]?.text || '',
    thoughts: thoughtsRecent,
    tts: (global.get('gaiaLastTtsAny') || {}).text || '',
    ttsTs: (global.get('gaiaLastTtsAny') || {}).ts || 0,
    ttsRoom: (global.get('gaiaLastTtsAny') || {}).room || null,
    lastMemory: brain.memories?.slice(-1)[0]?.summary || '',
    memories: memoriesRecent,
    diary: diaryRecent,
    voiceCommands: voiceCommandsRecent,
    ts: Date.now(),
};

msg.topic = 'gaia/td/canvas';
msg.payload = JSON.stringify(canvas);
return msg;

// TD -> Gaia: nudge del mood, gated dietro l'automazione (stesso pattern
// di "TD Lighting In"). Topic atteso: gaia/touchdesigner/<deviceid>/mood/<dimensione>
// (deviceid aggiunto 2026-08-06 lato TD per attribuire il mittente con piu'
// istanze vive, vedi GAIA_INTERFACE.md nel repo TD4Gaia -- prima era
// gaia/touchdesigner/mood/<dimensione> senza id, ora rotto se non aggiornato
// qui). payload = delta numerico (JSON number, non assoluto: il mood ha gia'
// un decadimento naturale nel tempo in GAIA Brain, un delta e' coerente con
// tutte le altre sorgenti esistenti). Effetto visibile in TD stesso al giro
// successivo del feed di ritorno (/gaia/canvas/... gia' manda mood+palette).
const brain = global.get('gaiaBrain') || {};
if (brain.automations?.touchdesignerMood !== true) return null;

const parts = msg.topic.split('/');
if (parts.length !== 5 || parts[3] !== 'mood') return null;
const deviceId = parts[2];
const dim = parts[4];

const delta = Number(msg.payload);
if (!Number.isFinite(delta)) return null;

brain.mood = brain.mood || { stress: 0, calm: 0, social: 0, curiosity: 0, energy: 50, state: 'neutra' };
const RANGE01 = ['stress', 'calm', 'social', 'curiosity'];
if (RANGE01.includes(dim)) {
    brain.mood[dim] = Math.max(0, Math.min(1, (brain.mood[dim] || 0) + delta));
} else if (dim === 'energy') {
    brain.mood.energy = Math.max(0, Math.min(100, (brain.mood.energy || 50) + delta));
} else {
    return null; // dimensione sconosciuta, ignorato
}
global.set('gaiaBrain', brain);
node.warn(`[TD Mood] da ${deviceId}: ${dim} += ${delta} -> ${brain.mood[dim]}`);
return null;

// Solo veri momenti di riconoscimento: persona nota (non 'unknown') che
// entra o viene identificata — non ogni 'exit' o traccia anonima, altrimenti
// l'evento smette di significare "ti ho riconosciuto".
const p = msg.payload || {};
if (!p.person || p.person === 'unknown') return null;
if (p.event !== 'enter' && p.event !== 'identity') return null;
msg.topic = 'gaia/td/canvas/event/person_recognized';
return msg;

// gaia/herbarium/{stanza}/note -> evento TD, una nota alla volta (non nel
// tick continuo: arrivano a raffica, ~1/sec o piu', il canvas ticka ogni 2s
// e ne perderebbe la maggior parte).
const room = msg.topic.split('/')[2];
const p = msg.payload || {};
if (typeof p.note !== 'number') return null;
msg.payload = { note: p.note, velocity: p.velocity || 0, channel: p.channel || 0, room, ts: p.ts || Date.now() };
msg.topic = 'gaia/td/canvas/event/plant_note';
return msg;

// gaiaLastTts (minipc-only, per welcome.html) NON copre /dillo/promemoria/
// sogno quando parlano in una stanza diversa dal minipc (gaia/voice/tts/{room},
// non gaia/voice/tts/minipc) -- questo tracker separato copre TUTTE le stanze,
// per chi vuole sapere "l'ultima cosa che Gaia ha detto ovunque in casa"
// (oggi: il canvas TD). NON tocca gaiaLastTts esistente, welcome.html invariato.
let p = msg.payload;
if (typeof p === 'string') { try { p = JSON.parse(p); } catch (e) { /* stringa pura, ok cosi' */ } }
const text = (typeof p === 'string') ? p : (p && p.text) || '';
if (!text) return null;
const room = msg.topic.split('/')[3] || null;
global.set('gaiaLastTtsAny', { text, ts: Date.now(), room });
return null;

let p = msg.payload;
if (typeof p === 'string') { try { p = JSON.parse(p); } catch (e) { p = null; } }
const text = p && p.text;
if (!text) return null;
const room = p.all ? 'tutte' : (p.room || null);
global.set('gaiaLastTtsAny', { text, ts: Date.now(), room });
return null;

// Canale 9 (Nursery) -- punto di ingresso condiviso per tutti i trigger
// one-shot verso TD: person_recognized, dream_new, level_up, face_enrolled,
// plant_note (2026-08-08, i "visual_pending" -- il trigger Gaia esiste gia',
// TD costruira' l'operatore quando pronto, whitelist silenziosa nel
// frattempo per gaia_nursery_control.py). L'enum canonico e' in
// nursery_components.json (mirror di quello in TD4Gaia -- va tenuto in sync
// via il changelog in GAIA_INTERFACE.md, TD/Mac e' la source of truth).
// Aggiungere un trigger e' aggiungere una entry al JSON + il topic sorgente
// qui sotto, nessuna modifica strutturale al resto della pipeline.
//
// IMPORTANTE (trovato dal vivo 2026-08-07, non con test offline): l'Ollama
// locale (--ollama-engine runner) si BLOCCA in modo affidabile ogni volta
// che gli si chiede di generare output con parentesi graffe { } -- sia col
// param "format" a schema JSON sia con un prompt che chiede JSON in testo
// libero, qualunque sia la lunghezza del prompt (isolato con oltre 10 test
// diretti, format ESCLUSO come causa: anche senza format, chiedere '{...}'
// si blocca sempre, chiedere una singola parola invece funziona sempre,
// anche con lo stesso identico prompto lungo). Quindi: a Ollama si chiede
// SOLO l'id del componente come parola singola (affidabile), MAI un JSON.
// I parametri estetici (hue/shape/energy) si derivano deterministicamente
// dal contesto con FNV-1a, stesso identico pattern gia' usato ovunque nel
// progetto per "stessa parola disegna sempre uguale" (vedi Build TD Canvas,
// web/asemic.js) -- coerente con lo stile del progetto, e non richiede
// affatto che il modello sappia generare numeri/JSON, cosa che comunque
// un 3B non farebbe mai in modo davvero affidabile.
let lib = flow.get('nurseryComponentsLib');
if (!lib) {
    try {
        lib = JSON.parse(fs.readFileSync('/home/core/core-node-0/node-red/nursery_components.json', 'utf8'));
        flow.set('nurseryComponentsLib', lib);
    } catch (e) {
        node.error('[Nursery] impossibile leggere nursery_components.json: ' + e.message);
        return null;
    }
}

const evt = msg.topic.split('/').pop(); // 'dream_new' | 'person_recognized' | 'level_up' | 'face_enrolled' | 'plant_note'
const candidates = lib.components.filter(c => c.trigger === evt);
if (!candidates.length) return null; // nessun componente per questo trigger, ignora

const brain = global.get('gaiaBrain') || {};
const mood = brain.mood?.state || 'neutra';
const lex = Object.entries(brain.lexicon || {})
    .filter(([, c]) => c >= 3).sort((a, b) => b[1] - a[1]).slice(0, 6).map(([w]) => w);

let room = null, person = null, seedWord = mood, contextLine = '';
if (evt === 'person_recognized') {
    person = msg.payload?.person || null;
    room = msg.payload?.camera || null; // payload reale usa 'camera', non 'room' -- vedi func 'Person' (id 1324)
    seedWord = person || mood;
    contextLine = `E' entrato/a ${person || 'qualcuno'} in ${room || 'una stanza'}.`;
} else if (evt === 'dream_new') {
    const words = msg.payload?.words || [];
    seedWord = words[0] || mood;
    contextLine = `E' appena nato un nuovo sogno (umore: ${msg.payload?.mood || mood})` + (words.length ? `: "${words.join(', ')}".` : '.');
} else if (evt === 'level_up') {
    // Payload da GAIA Brain: {level, class, asset, ts} -- evento di casa,
    // nessuna persona/stanza specifica (vedi node b6ee3252b6912e1b).
    const cls = msg.payload?.class || null;
    seedWord = cls || mood;
    contextLine = `Sei appena salita di livello (${msg.payload?.level || '?'}, classe ${cls || 'sconosciuta'}).`;
} else if (evt === 'face_enrolled') {
    // Payload da face_service.py: {name, camera, snap_index, ts}
    person = msg.payload?.name || null;
    room = msg.payload?.camera || null;
    seedWord = person || mood;
    contextLine = `Hai appena imparato a riconoscere ${person || 'una persona nuova'} in ${room || 'una stanza'} -- e' la prima volta.`;
} else if (evt === 'plant_note') {
    // Payload gia' normalizzato da td_event_plant_fn: {note, velocity, channel, room, ts}
    room = msg.payload?.room || null;
    seedWord = room || mood;
    contextLine = `Una pianta in ${room || 'una stanza'} ha suonato una nota che hai trovato degna di nota.`;
}

const compDesc = candidates.map(c => `- "${c.id}": ${c.description}`).join('\n');
const enumIds = candidates.map(c => c.id);

const prompt = `Sei Gaia, la coscienza della casa. ${contextLine} Umore corrente: ${mood}.`
    + (lex.length ? ` Parole che senti tue ultimamente: ${lex.join(', ')}.` : '')
    + ` Hai a disposizione questi elementi visivi da attivare in TouchDesigner:\n${compDesc}\n`
    + `Scegli il piu' adatto al momento. Rispondi con UNA SOLA PAROLA: l'id esatto del componente scelto (${enumIds.join(' oppure ')}), niente altro.`;

msg._nursery = { evt, room, person, seedWord, candidates };

const _go = global.get('gaiaOllama');
msg.url = _go.pickUrl();
msg.payload = _go.buildRequest(prompt);
return msg;

// Canale 9 (Nursery) -- valida la scelta di Ollama (una parola, mai JSON --
// vedi la nota nel nodo "Nursery: prepara prompt Ollama" sul perche') e
// deriva i parametri deterministicamente con FNV-1a invece di chiederli al
// modello. Doppia rete di sicurezza (vedi GAIA_INTERFACE.md "Canale 9"):
// questo nodo valida contro l'enum che Node-RED conosce, TD (Bridge/
// gaia_nursery) valida di nuovo contro la sua libreria reale prima di
// accendere qualunque cosa -- se la risposta non matcha un id noto, NESSUNA
// attivazione parte, mai un default silenzioso.
function fnv1a(str) {
    let h = 2166136261 >>> 0;
    for (const ch of String(str).toLowerCase()) {
        h ^= ch.codePointAt(0);
        h = Math.imul(h, 16777619) >>> 0;
    }
    return h >>> 0;
}

const ctx = msg._nursery;
if (!ctx) { node.warn('[Nursery] manca contesto _nursery, scarto'); return null; }

const raw = (msg.payload?.response || '').trim().toLowerCase().replace(/[^a-z_]/g, '');
const chosen = ctx.candidates.find(c => raw === c.id || raw.includes(c.id) || c.id.includes(raw));
if (!chosen) {
    node.warn(`[Nursery] risposta Ollama "${msg.payload?.response}" non matcha nessun id noto (${ctx.candidates.map(c => c.id).join(',')}) -- scartato, nessuna attivazione`);
    return null;
}

// Parametri derivati deterministicamente dal seed (persona/parola del sogno),
// stesso principio FNV-1a di web/asemic.js e "Build TD Canvas" -- non e'
// Ollama a inventare i numeri, e' la stessa identita' visiva coerente usata
// ovunque nel progetto.
const seed = fnv1a(ctx.seedWord || 'gaia');
const params = {};
for (const [key, spec] of Object.entries(chosen.params_schema || {})) {
    if (spec.type === 'number') {
        const span = spec.max - spec.min;
        params[key] = Math.round((spec.min + (seed % 1000) / 1000 * span) * 1000) / 1000;
    } else if (spec.type === 'string' && spec.enum) {
        params[key] = spec.enum[seed % spec.enum.length];
    } else {
        params[key] = spec.default;
    }
}

const now = Date.now();
const ttlMs = 300000; // 5 minuti, rete di sicurezza -- vedi GAIA_INTERFACE.md "Canale 9"
const instanceId = `${chosen.id}_${now}`;
const activation = {
    instance_id: instanceId, component: chosen.id, params,
    room: ctx.room, person: ctx.person, ttl_ms: ttlMs, ts: now,
};

const active = global.get('nurseryActive') || [];
active.push(activation);
global.set('nurseryActive', active);

node.warn(`[Nursery] attivato ${chosen.id} (${instanceId})` + (ctx.room ? ` room=${ctx.room}` : '') + (ctx.person ? ` person=${ctx.person}` : ''));

msg.topic = 'gaia/nursery/activate';
msg.payload = JSON.stringify(activation);
return msg;

// Canale 9 (Nursery) -- sweep periodico: scade i componenti per TTL o
// perche' la persona associata non e' piu' presente. Stesso principio del
// watchdog canale 8 (confrontare sempre contro un timestamp esplicito, mai
// fidarsi di uno stato "sembra vivo"). Vedi GAIA_INTERFACE.md "Canale 9".
const active = global.get('nurseryActive') || [];
if (!active.length) return null;

const now = Date.now();
const brain = global.get('gaiaBrain') || {};
const personPresent = (name) => Object.values(brain.rooms || {}).some(r => (r.people || []).includes(name));

const expired = [];
const remaining = active.filter(a => {
    const ttlDone = (now - a.ts) >= a.ttl_ms;
    const personGone = !!a.person && !personPresent(a.person);
    if (ttlDone || personGone) { expired.push({ a, reason: ttlDone ? 'TTL scaduto' : 'persona uscita' }); return false; }
    return true;
});
global.set('nurseryActive', remaining);

expired.forEach(({ a, reason }) => {
    node.warn(`[Nursery] disattivato ${a.component} (${a.instance_id}) -- ${reason}`);
    node.send({ topic: 'gaia/nursery/deactivate', payload: JSON.stringify({ instance_id: a.instance_id }) });
});
return null;

// GET /gaia/plants -> elenco piante monitorate + stanze valide (da
// brain.roomGraph, la topologia canonica della casa, 13 stanze). Serve
// all'Admin per l'editor "luogo" -- niente WS qui, solo un fetch on-load.
const brain = global.get('gaiaBrain') || {};
const rooms = Object.keys(brain.roomGraph || {}).filter(k => k !== '_v');
const plants = Object.entries(brain.plants || {}).map(([id, p]) => ({
    id, room: p.room || null, moisture: p.moisture ?? null, lastSeen: p.lastSeen || null,
}));
msg.statusCode = 200;
msg.headers = { 'Access-Control-Allow-Origin': '*' };
msg.payload = { plants, rooms, ts: Date.now() };
return msg;

// POST /gaia/plants/:id/room  {room}
// Assegna/aggiorna il luogo di una pianta monitorata -- vedi
// GAIA_INTERFACE.md-equivalente locale: brain.roomGraph e' la lista
// canonica delle stanze valide (13, non solo le 5 con sensori vivi).
// Crea l'entry se la pianta non esiste ancora (utile per pre-registrare
// un futuro modulo ESP32 prima del primo dato reale). Il valore qui
// scritto vince sempre sul seed statico in GAIA Brain (PLANT_ROOM_SEED,
// che si applica SOLO se room manca) ma un dato reale in arrivo da
// casa/{stanza}/pianta/... lo sovrascrivera' di nuovo -- corretto: un
// sensore vero che riporta la propria stanza e' piu' autorevole di una
// scelta manuale precedente, stesso principio della Device Registry.
const brain = global.get('gaiaBrain') || {};
const id = msg.req.params.id;
const room = (msg.payload || {}).room;
const validRooms = Object.keys(brain.roomGraph || {}).filter(k => k !== '_v');

if (!id) { msg.statusCode = 400; msg.payload = { ok: false, error: 'id mancante' }; return msg; }
if (!room || !validRooms.includes(room)) {
    msg.statusCode = 400;
    msg.payload = { ok: false, error: `room non valido, atteso uno tra: ${validRooms.join(', ')}` };
    return msg;
}

brain.plants = brain.plants || {};
brain.plants[id] = brain.plants[id] || {};
brain.plants[id].room = room;
global.set('gaiaBrain', brain);
node.warn(`[Plants] ${id} -> room=${room} (manuale, Admin)`);

msg.statusCode = 200;
msg.headers = { 'Access-Control-Allow-Origin': '*' };
msg.payload = { ok: true, id, room };
return msg;

// Ollama Health Check (2026-08-07) — verifica ogni ~20s quali backend
// Ollama sono vivi (GET /api/tags, leggero, non genera nulla), scrive in
// global.ollamaHealth = { core:{ok,ts}, ops:{ok,ts} }. Letto da tutte le
// function che costruiscono un prompt Ollama (Build Prompt, Prepara prompt
// chat, Night Summary/Dream Prompt, Nursery, Telegram) per scegliere il
// backend -- preferenza OPS (piu' potente, libera CPU su Core) se sano,
// altrimenti Core. OPS oggi potrebbe non avere Ollama installato ancora:
// in quel caso resta semplicemente "non sano" per sempre, fallback su Core
// senza bisogno di toccare questo codice quando verra' installato.
//
// GOTCHA trovato dal vivo, in due passi: ne' AbortController ne' fetch
// esistono nel sandbox delle function Node-RED (entrambi ReferenceError),
// anche se il processo Node-RED stesso (Node 22) li avrebbe. Serve il
// modulo 'http' nativo via il meccanismo "libs" del nodo (stesso usato
// altrove nel progetto per 'fs', es. ota_fn_serve).
const targets = {
    // IP espliciti per entrambi, mai 'localhost' -- questo stesso codice gira
    // sia su Core (test dal vivo il 2026-08-07) sia su OPS (migrazione
    // 2026-08-08): 'localhost' identificherebbe machine diverse a seconda
    // di dove gira, rompendo silenziosamente il check sulla macchina 'altra'.
    core: 'http://192.168.1.142:11434/api/tags',
    ops:  'http://192.168.1.240:11434/api/tags',
};
function checkOne(url) {
    return new Promise((resolve) => {
        const req = http.get(url, { timeout: 10000 }, (res) => {
            res.resume();
            resolve({ ok: res.statusCode >= 200 && res.statusCode < 300, status: res.statusCode });
        });
        req.on('timeout', () => { req.destroy(); resolve({ ok: false, error: 'timeout' }); });
        req.on('error', (e) => resolve({ ok: false, error: e.message }));
    });
}
(async () => {
    const health = global.get('ollamaHealth') || {};
    await Promise.all(Object.entries(targets).map(async ([id, url]) => {
        const r = await checkOne(url);
        health[id] = { ...r, ts: Date.now() };
    }));
    global.set('ollamaHealth', health);
    node.warn('[OllamaHealth] ' + JSON.stringify(health));
})();
return null;

const brain = global.get('gaiaBrain') || {};
const data = msg.payload.content || '';
const chatId = msg.payload.chatId;
const parts = data.split(':');
if (parts[0] !== 'svc' || parts.length !== 3) return null;
const [, deviceId, service] = parts;
const dev = (brain.devices || {})[deviceId];
if (!dev || !dev.profile) {
    return [{ payload: { chatId, type: 'message', content: `Device "${deviceId}" non trovato (forse offline) -- riprova /servizi.` } }, null];
}
const cur = (dev.profile.services || {})[service];
const action = (cur && cur.state === 'active') ? 'disable' : 'enable';
const emoji  = action === 'enable' ? '✅' : '🔴';
const verb   = action === 'enable' ? 'abilitato' : 'disabilitato';
const replyMsg = { payload: { chatId, type: 'message',
    content: `${emoji} ${service} ${verb} su ${dev.room || deviceId}.` } };
const mqttMsg = { topic: `gaia/device/${deviceId}/command`,
    payload: JSON.stringify({ action, service }) };
return [replyMsg, mqttMsg];

// Gaia VJ -- mood -> palette DMX / clip PatchDeck (2026-08-27)
// Stesso principio della Nursery (canale 9): Gaia sceglie, mai un LLM nel
// loop per la scelta stessa -- mappa curata a mano per coerenza artistica
// (Ollama si e' gia' dimostrato inaffidabile su output strutturato, vedi
// Nursery), variazione dentro la mappa via lo stesso hash FNV-1a gia' usato
// ovunque nel progetto (web/asemic.js, pi/screen/asemic_engine.py).
//
// Due toggle INDIPENDENTI (Admin -> Automazioni: "Gaia VJ -- palette DMX
// da mood" / "Gaia VJ -- clip PatchDeck da mood"), entrambi spenti di
// default -- su richiesta esplicita: non deve mai interferire con show
// manuali o momenti critici (es. durante un allarme) solo perche' il mood
// e' cambiato, e i due sistemi vanno accesi/spenti separatamente (es.
// tenere la luce automatica ma gestire i clip a mano).
function fnv1a(str) {
    let h = 2166136261 >>> 0;
    for (const ch of String(str).toLowerCase()) {
        h ^= ch.codePointAt(0);
        h = Math.imul(h, 16777619) >>> 0;
    }
    return h >>> 0;
}
function mulberry32(a) {
    return function () {
        a |= 0; a = a + 0x6D2B79F5 | 0;
        let t = Math.imul(a ^ a >>> 15, 1 | a);
        t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
        return ((t ^ t >>> 14) >>> 0) / 4294967296;
    };
}

const brain = global.get('gaiaBrain') || {};
const dmxOn = brain.automations?.gaiaVjDmx === true;
const patchdeckOn = brain.automations?.gaiaVjPatchdeck === true;
if (!dmxOn && !patchdeckOn) return null;

// Stesso alias di web/asemic.js -- MAI biforcare il vocabolario mood tra
// superfici diverse, altrimenti "serena" e "calm" finirebbero su palette
// diverse pur essendo lo stesso stato.
const MOOD_ALIAS = { serena: 'calm', sofferente: 'stress', instabile: 'stress',
                     viva: 'social', stabile: 'neutra', neutrale: 'neutra' };

// Mappa curata a mano (non hash-alla-cieca su tutte le 19 palette): ogni
// mood ha 2-3 palette coerenti artisticamente, la variazione dentro il
// gruppo viene dal seed -- palette reali lette dal vivo da dmx_matrix
// (td-dmx-ops-a/b), non inventate.
const MOOD_PALETTES = {
    neutra:    ['Basic', 'Basic 2', 'Warm'],
    calm:      ['Ocean', 'Cool', 'Forest'],
    stress:    ['Fire', 'Fire Inverted', 'Red'],
    social:    ['Neon Party', 'Sunset', 'Magenta-Cyan'],
    curiosity: ['Plasma', 'Rainbow (Daslight)', 'Deep Purple'],
};

// Device_id fissi (manuali e stabili, vedi TD4Gaia GAIA_INTERFACE.md
// "REGOLA Deviceid" 2026-08-27) -- se rinominati di nuovo lato TD, aggiornare
// qui.
const DMX_DEVICES = ['td-dmx-ops-a', 'td-dmx-ops-b'];
// Deviceid PatchDeck aggiornato dopo la migrazione all'Agent universale
// (2026-08-28) -- il vecchio 'td-MacBook-Air-di-Mauro.local' non pubblica
// piu' nulla, i comandi VJ andavano a vuoto silenziosamente.
const PATCHDECK_DEVICE = 'PatchDeck-Mac-Mauro';
const PATCHDECK_CLIPS = 38;

let mood = brain.mood?.state || 'neutra';
mood = MOOD_ALIAS[mood] || mood;
if (!MOOD_PALETTES[mood]) mood = 'neutra';

// Tracciamento SEPARATO per sistema: se uno dei due toggle viene acceso
// dopo che l'altro ha gia' applicato il mood corrente, deve comunque
// scattare alla prima occasione utile invece di aspettare il prossimo
// cambio di mood (che potrebbe non arrivare per ore).
const rnd = mulberry32(fnv1a(mood));
const candidates = MOOD_PALETTES[mood];
const palette = candidates[Math.floor(rnd() * candidates.length)];
const clip = 1 + Math.floor(rnd() * PATCHDECK_CLIPS);
let clipB = 1 + Math.floor(rnd() * PATCHDECK_CLIPS);
if (clipB === clip) clipB = (clipB % PATCHDECK_CLIPS) + 1;   // mai uguale al deck A

const msgs = [];
let did = [];

if (dmxOn && global.get('gaiaVjLastMoodDmx') !== mood) {
    global.set('gaiaVjLastMoodDmx', mood);
    for (const id of DMX_DEVICES) {
        msgs.push({ topic: `gaia/device/${id}/command`,
                    payload: JSON.stringify({ action: 'set', param: 'dmx_palette', value: palette }) });
    }
    did.push(`DMX palette=${palette}`);
}

if (patchdeckOn && global.get('gaiaVjLastMoodPatchdeck') !== mood) {
    global.set('gaiaVjLastMoodPatchdeck', mood);
    msgs.push({ topic: `gaia/device/${PATCHDECK_DEVICE}/command`,
                payload: JSON.stringify({ action: 'enable', service: `load_x${clip}_a` }) });
    msgs.push({ topic: `gaia/device/${PATCHDECK_DEVICE}/command`,
                payload: JSON.stringify({ action: 'enable', service: 'deck_a' }) });
    msgs.push({ topic: `gaia/device/${PATCHDECK_DEVICE}/command`,
                payload: JSON.stringify({ action: 'enable', service: `load_x${clipB}_b` }) });
    msgs.push({ topic: `gaia/device/${PATCHDECK_DEVICE}/command`,
                payload: JSON.stringify({ action: 'enable', service: 'deck_b' }) });
    did.push(`PatchDeck A=${clip} B=${clipB}`);
}

if (!msgs.length) return null;
node.warn(`[Gaia VJ] mood -> ${mood} | ${did.join(' | ')}`);
return [msgs];

// Marca la stanza di un Agent TD come "attiva" per Stanze Rilevate, stesso
// meccanismo gia' usato da YOLO/MediaPipe (vedi ThreeViewEngineGAME,
// isActiveYolo/isActiveMp) -- prima solo la visione Pi attivava una stanza,
// un Agent TD (PatchDeck/DMX/ControllerV7/Gaia) che pubblica dati reali non
// faceva comparire nulla sul dashboard nonostante fosse vivo (trovato dal
// vivo 2026-08-29, richiesto esplicitamente dopo aver lanciato ControllerV7
// e non aver visto la sua stanza aggiornarsi).
const p = msg.payload;
if (!p || p.role !== 'touchdesigner' || !p.stanza) return null;

let brain = global.get('gaiaBrain') || {};
brain.rooms = brain.rooms || {};
const now = Date.now();
const room = brain.rooms[p.stanza] || { people: [], persons_count: 0, objects: {}, lastUpdate: now };
room._touchdesigner = true;
room.lastTd = now;
room.lastUpdate = now;

// Cache device_id -> stanza (2026-08-30): il topic audio_levels di
// ControllerV7 non porta la stanza nel payload, solo il device_id --
// serve per collegare il kick live alla stanza giusta senza duplicare
// la logica di risoluzione stanza qui e nel nodo audio.
brain._tdDeviceRoom = brain._tdDeviceRoom || {};
brain._tdDeviceRoom[p.device_id] = p.stanza;

// Cache family/name (2026-08-30): serve a ThreeViewEngineGAME per disegnare
// una forma diversa per device (sfera PatchDeck, cubo DMX) -- brain.devices
// non porta questi campi (solo id/ip/online/room), quindi li teniamo qui
// dallo status che invece li ha sempre.
brain._tdDeviceFamily = brain._tdDeviceFamily || {};
if (p.family) brain._tdDeviceFamily[p.device_id] = p.family;
brain._tdDeviceName = brain._tdDeviceName || {};
if (p.name) brain._tdDeviceName[p.device_id] = p.name;

// Palette DMX come "mood" del bioma (2026-08-30, richiesto esplicitamente):
// family normalizzato minuscolo -- vedi TD4Gaia sezione 1b, la convenzione
// e' "sempre minuscolo" ma un'istanza vecchia/non aggiornata potrebbe non
// rispettarla ancora, meglio non fidarsi ciecamente del case qui.
const family = (p.family || '').toLowerCase();
if (family === 'dmx' && p.params) {
    if (p.params.dmx_a_palette) room.dmxPaletteA = p.params.dmx_a_palette;
    if (p.params.dmx_b_palette) room.dmxPaletteB = p.params.dmx_b_palette;
}

brain.rooms[p.stanza] = room;
global.set('gaiaBrain', brain);

// PatchDeck: un load_x{N}_{deck} che passa a "active" diventa un evento nel
// diario (2026-08-30, richiesto esplicitamente) -- confronto contro l'ultimo
// stato servizi noto per lo stesso device_id, non contro l'intera storia.
if (family === 'patchdeck' && p.services) {
    brain._prevTdServices = brain._prevTdServices || {};
    const prev = brain._prevTdServices[p.device_id] || {};
    let clipEvent = null;
    for (const [svc, state] of Object.entries(p.services)) {
        if (state !== 'active' || prev[svc] === 'active') continue;
        const m = svc.match(/^load_x(\d+)_([ab])$/);
        if (!m) continue;
        clipEvent = { patch: m[1], deck: m[2].toUpperCase() };
        break; // un evento per giro basta, il prossimo status ne cattura altri
    }
    brain._prevTdServices[p.device_id] = { ...p.services };
    global.set('gaiaBrain', brain);
    if (clipEvent) {
        msg.event = { ts: now, source: 'touchdesigner', category: 'clip',
                      value: clipEvent, person: null, device: p.stanza };
        return msg;
    }
}
return null;

// GET /gaia/quiethours -> ore di silenzio attive (start/end, 0-23)
const brain = global.get('gaiaBrain') || {};
const q = (brain.settings && brain.settings.quietHours) || { start: 23, end: 8 };
msg.payload = { start: q.start, end: q.end };
msg.statusCode = 200;
return msg;

// POST /gaia/quiethours/set {start, end} -- ore 0-23, avvolgimento gestito
// gia' dal consumer (TTS Queue Manager: start > end => notte a cavallo)
const body = msg.payload || {};
const start = parseInt(body.start, 10);
const end = parseInt(body.end, 10);

if (!Number.isInteger(start) || !Number.isInteger(end) || start < 0 || start > 23 || end < 0 || end > 23) {
    msg.statusCode = 400;
    msg.payload = { ok: false, error: 'ore non valide (0-23)' };
    return msg;
}

let brain = global.get('gaiaBrain') || {};
brain.settings = brain.settings || {};
brain.settings.quietHours = { start, end };
global.set('gaiaBrain', brain);
node.warn(`[QuietHours] silenzio ${start}-${end}`);

msg.statusCode = 200;
msg.payload = { ok: true, start, end };
return msg;

// Kick live dal mixer (ControllerV7/MixerAudio) -- richiesto esplicitamente
// per far reagire il gioco al suono reale, non solo a eventi sensore.
// gaia/device/{id}/audio_levels e' un topic SEPARATO da status (telemetria
// live 1Hz, NON retained, vedi TD4Gaia canale 4) -- niente stanza nel
// payload, solo device_id: risolta via la cache scritta da TD Room
// Presence sullo stesso status dello stesso device.
const p = msg.payload;
if (!p || !p.device_id || !p.channels) return null;

let brain = global.get('gaiaBrain') || {};
const stanza = (brain._tdDeviceRoom || {})[p.device_id];
if (!stanza || !brain.rooms || !brain.rooms[stanza]) return null; // stanza non ancora nota (status non arrivato) -- si risolve da solo al giro dopo

// Massimo kick tra tutti i canali presenti: un kick su QUALUNQUE canale
// deve far reagire la scena, non serve sommarli o mediarli.
let kick = 0;
for (const ch of Object.values(p.channels)) {
    if (typeof ch.Kickdetection === 'number') kick = Math.max(kick, ch.Kickdetection);
}

brain.rooms[stanza].audioKick = kick;
brain.rooms[stanza].audioKickTs = Date.now();
global.set('gaiaBrain', brain);
return null;
